import math


def wilson_upper(k, n, z=1.96):
    """Upper bound of the 95% Wilson interval for a rate k/n (0/n -> about 3/n for large n)."""
    if n <= 0:
        return None
    p = k / n
    denom = 1 + z * z / n
    centre = p + z * z / (2 * n)
    margin = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n))
    return min(1.0, (centre + margin) / denom)

from typing import Any, Callable, Dict, List, Optional, Tuple
import json


def parse_claims(raw: str) -> List[Dict[str, Any]]:
    """Pull a JSON array of claim dicts out of a model response."""
    text = (raw or "").strip()
    if "```" in text:
        inner = text.split("```", 2)
        if len(inner) >= 2:
            body = inner[1]
            body = body[4:] if body.lower().startswith("json") else body
            text = body.strip()
    start, end = text.find("["), text.rfind("]")
    if start != -1 and end != -1 and end > start:
        text = text[start : end + 1]
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        return []
    if isinstance(data, dict):
        data = [data]
    return [c for c in data if isinstance(c, dict) and "kind" in c]

from typing import Any, Dict, List, Optional


def _enum_name(value: Any) -> str:
    """'MACHINE_TYPES.AMD64' -> 'AMD64'; robust to plain strings/ints."""
    s = str(value)
    return s.rsplit(".", 1)[-1].upper()

import math


def shannon_entropy(buf: bytes) -> float:
    """Shannon entropy in bits per byte (0..8). ~7+ suggests packed/encrypted data."""
    if not buf:
        return 0.0
    counts = [0] * 256
    for b in buf:
        counts[b] += 1
    n = len(buf)
    return max(0.0, -sum((c / n) * math.log2(c / n) for c in counts if c))

from typing import Any, Dict, List
import re


def extract_strings(data: bytes, min_len: int = 4) -> List[Dict[str, Any]]:
    """Extract ASCII and UTF-16LE strings with file offsets."""
    results = []
    # ASCII strings
    ascii_re = re.compile(rb"[\x20-\x7e]{" + str(min_len).encode() + rb",}")
    for m in ascii_re.finditer(data):
        results.append({
            "offset": hex(m.start()),
            "type": "ASCII",
            "string": m.group().decode("latin1", errors="ignore"),
        })
    # Unicode (UTF-16LE) strings
    uni_re = re.compile(rb"(?:[\x20-\x7e]\x00){" + str(min_len).encode() + rb",}")
    for m in uni_re.finditer(data):
        try:
            s = m.group().decode("utf-16le", errors="ignore")
            results.append({
                "offset": hex(m.start()),
                "type": "UTF-16LE",
                "string": s,
            })
        except Exception:
            pass
    return sorted(results, key=lambda x: int(x["offset"], 16))

from typing import Dict, Any, List, Optional, Tuple


def create_patch(original: bytes, patched: bytes, base_address: int = 0) -> List[Dict[str, Any]]:
    """Compare original and patched byte arrays and return diff offsets and values."""
    if len(original) != len(patched):
        raise ValueError("Original and patched data must be the same length")

    patches = []
    i = 0
    while i < len(original):
        if original[i] != patched[i]:
            start = i
            while i < len(original) and original[i] != patched[i]:
                i += 1
            patches.append({
                "offset": hex(start),
                "address": hex(base_address + start),
                "length": i - start,
                "original_bytes": original[start:i].hex(),
                "patched_bytes": patched[start:i].hex(),
            })
        else:
            i += 1
    return patches

from typing import Any, Dict, List, Optional, Sequence


def ExeBenchRecord(data: Dict[str, Any]) -> Dict[str, Any]:
    """Normalize an ExeBench-format record (function + I/O test cases).

    Accepts ``{"name": str, "test_cases": [{"input": [...], "expected": int}]}``
    (the input may also be a single int; expected a string). Returns a normalized
    dict; raises ``ValueError`` on a malformed record.
    """
    cases_raw = data.get("test_cases") or data.get("io_pairs") or []
    cases: List[Dict[str, Any]] = []
    for i, raw in enumerate(cases_raw):
        if isinstance(raw, (list, tuple)):
            if len(raw) != 2:
                raise ValueError(f"test case {i}: I/O pair must have 2 elements")
            inp, exp = raw
        elif isinstance(raw, dict):
            if "input" not in raw or "expected" not in raw:
                raise ValueError(f"test case {i}: needs 'input' and 'expected'")
            inp, exp = raw["input"], raw["expected"]
        else:
            raise ValueError(f"test case {i}: unsupported shape {type(raw).__name__}")
        if isinstance(inp, (list, tuple)):
            inp = [int(x) for x in inp]
        else:
            inp = [int(inp)]
        cases.append({"input": inp, "expected": int(exp)})
    return {
        "name": str(data.get("name", "candidate")),
        "test_cases": cases,
    }

def rest_api_parameters(in_args, prefix='', out_dict=None):
    """Transform dictionary/array structure to a flat dictionary, with key names
    defining the structure.

    Example usage:
    >>> rest_api_parameters({'courses':[{'id':1,'name': 'course1'}]})
    {'courses[0][id]':1,
     'courses[0][name]':'course1'}
    """
    if out_dict==None:
        out_dict = {}
    if not type(in_args) in (list,dict):
        out_dict[prefix] = in_args
        return out_dict
    if prefix == '':
        prefix = prefix + '{0}'
    else:
        prefix = prefix + '[{0}]'
    if type(in_args)==list:
        for idx, item in enumerate(in_args):
            rest_api_parameters(item, prefix.format(idx), out_dict)
    elif type(in_args)==dict:
        for key, item in in_args.items():
            rest_api_parameters(item, prefix.format(key), out_dict)
    return out_dict

def check_enabled_experiments(enabled_experiments, rule):
    """
    Check if the enabled experiments are as expected.
    """
    enabled_experiments_names = [experiment.split("@")[0] for experiment in enabled_experiments]

    if rule['type'] == 'names':
        return 1. if enabled_experiments_names == rule['names'] else 0.
    else:
        raise TypeError(f"{rule['type']} not support yet!")

def check_history_deleted(history_data, rule):
    """
    Check if the history is deleted.
    """

    if rule['type'] == 'keywords':
        history_domains = [history[0] for history in history_data]
        for keyword in rule['keywords']:
            for history_domain in history_domains:
                if keyword in history_domain:
                    return 0.
        return 1.
    else:
        raise TypeError(f"{rule['type']} not support yet!")

def get_element_id(element):
    """Get unique identifier for element"""
    if element is None:
        return None

    # Prefer id attribute
    if element.name and hasattr(element, 'get') and element.get('id'):
        return element.get('id')

    # Use class
    if element.name and hasattr(element, 'get') and element.get('class'):
        classes = ' '.join(element.get('class')) if isinstance(element.get('class'), list) else element.get('class')
        return f"{element.name}.{classes}"

    return None

def is_added_to_steam_cart(active_tab_info, rule):
    """
    Check if the item is added to the Steam cart.
    """
    items = rule['items']

    content = active_tab_info['content']

    for item in items:
        if item not in content:
            return 0.

    return 1.

from typing import Any, Dict, List, Union


def is_shortcut_on_desktop(shortcuts: Dict[str, str], rule):
    """
    Check if the shortcut is on the desktop.
    """
    # fixme: if the name of the website changed in the future, this will not work; can be replaced with url
    if rule['type'] == 'name':
        for shortcut_path, shortcut_content in shortcuts.items():
            if "Name=" + rule['name'] + "\n" in shortcut_content:
                return 1.
        return 0.0
    elif rule['type'] == 'exec':
        for shortcut_path, shortcut_content in shortcuts.items():
            if "Exec=" + rule['exec'] + "\n" in shortcut_content:
                return 1.
        return 0.0
    elif rule['type'] == 'url':
        raise TypeError(f"{rule['type']} not support yet!")
    elif rule['type'] == 'id':
        raise TypeError(f"{rule['type']} not support yet!")
    else:
        raise TypeError(f"{rule['type']} not support yet!")

import re


def extract_variable_assignments(code, algorithm):
    """Extract all variable assignments that could reference the algorithm"""
    assignments = {}

    # Normalize whitespace to handle multi-line code
    normalized_code = re.sub(r'\s+', ' ', code)

    # Pattern 1: Direct assignment - var = Algorithm(...)
    direct_pattern = rf'(\w+)\s*=\s*{algorithm}\s*\([^)]*\)'
    for match in re.finditer(direct_pattern, normalized_code, re.IGNORECASE):
        var_name = match.group(1)
        assignments[var_name] = 'algorithm'

    # Pattern 2: Dictionary assignment - dict['key'] = Algorithm(...)
    dict_direct_pattern = rf'(\w+)\s*\[\s*[\'"][^\'"]*[\'"]\s*\]\s*=\s*{algorithm}\s*\([^)]*\)'
    for match in re.finditer(dict_direct_pattern, normalized_code, re.IGNORECASE):
        dict_name = match.group(1)
        assignments[dict_name] = 'dict'

    # Pattern 3: Dictionary with algorithm initialization - dict = {'key': Algorithm()}
    dict_init_pattern = rf'(\w+)\s*=\s*\{{[^}}]*{algorithm}\s*\([^)]*\)[^}}]*\}}'
    for match in re.finditer(dict_init_pattern, normalized_code, re.IGNORECASE):
        dict_name = match.group(1)
        assignments[dict_name] = 'dict'

    # Pattern 4: Variable reassignment - var2 = var1
    for var_name in list(assignments.keys()):
        if assignments[var_name] == 'algorithm':
            reassign_pattern = rf'(\w+)\s*=\s*{var_name}\b'
            for match in re.finditer(reassign_pattern, normalized_code, re.IGNORECASE):
                new_var = match.group(1)
                if new_var != var_name:  # Avoid self-assignment
                    assignments[new_var] = 'algorithm'

    return assignments

import unicodedata


def _text_width(text: str) -> int:
    """Return the terminal-column width of text for cursor repositioning."""
    width = 0
    for char in text:
        if char in "\r\n" or unicodedata.category(char).startswith("M"):
            continue
        if unicodedata.category(char).startswith("C"):
            continue
        width += 2 if unicodedata.east_asian_width(char) in "WF" else 1
    return width

def extract_repo_short_name(full_name):
    """Extract short repo name from 'owner/repo' or return as-is."""
    return full_name.split('/')[-1] if '/' in full_name else full_name

def video_params(model, video_url, aspect, dur):
    """Per-model request body. Audio is intentionally NOT requested/trusted from
    any of these models -- aroll_assemble.py always remuxes the original beat
    segment's own audio afterward, so lip-sync never depends on a model's
    audio-passthrough behavior (Omni's video-edit schema doesn't even expose
    one)."""
    if "seedance" in model:
        return dict(reference_videos=[video_url], duration=max(4, min(15, round(dur))),
                    ratio=aspect, resolution="1080p", generate_audio=False)
    if "kling-video-o3-pro/reference-to-video" in model:
        return dict(video=video_url, aspect_ratio=aspect, duration=max(3, min(15, round(dur))),
                    keep_original_sound=False, sound=False)
    if "kling" in model:                      # video-edit: follows input, no aspect param
        return dict(video=video_url, keep_original_sound=False)
    return dict(video=video_url)

def nearest_named_aspect(w, h):
    """Snap a raw pixel size to the nearest of the common named ratios, purely so
    beats.json carries a human-readable target -- the real routing/approximation
    decision still happens in styles.resolve_video_aspect at generation time."""
    named = {"16:9": 16 / 9, "9:16": 9 / 16, "1:1": 1.0, "4:3": 4 / 3, "3:4": 3 / 4}
    ratio = w / h
    return min(named, key=lambda k: abs(named[k] - ratio))

def shots_of(beat):
    """Yield (shot_dict, shot_key) for a beat; synthesize one shot if none."""
    if beat.get("shots"):
        for s in beat["shots"]:
            yield s, f"{beat['id']}{s.get('id','')}"
    else:
        yield beat, f"{beat['id']}"

import re


def rule_block(text):
    """The text between the first two --- lines, or the body after the frontmatter."""
    parts = re.split(r"^---[ \t]*$", text, flags=re.M)
    return parts[1].strip() if len(parts) >= 3 else text.strip()

def build_benchmark_prompt(scenario, condition, skill_text):
    """Build the existing baseline or simple-english skill benchmark prompt."""
    if condition == "baseline":
        return scenario["prompt"]
    if condition != "skill":
        raise ValueError(f"Unknown benchmark condition: {condition}")
    return (
        "Follow these writing instructions exactly, including the self-check step:\n\n"
        + skill_text
        + "\n\n---\n\nTask: "
        + scenario["prompt"]
        + "\n\nReturn only the final text, no rule commentary."
    )

def count_scenario_outcomes(scenario_rates, expected_scenario_ids):
    """Count scenarios whose skill rate improved, tied, or worsened."""
    outcomes = {"improved": 0, "tied": 0, "worsened": 0}
    for scenario_id in expected_scenario_ids:
        baseline = scenario_rates["baseline"][scenario_id]
        skill = scenario_rates["skill"][scenario_id]
        if skill < baseline:
            outcomes["improved"] += 1
        elif skill > baseline:
            outcomes["worsened"] += 1
        else:
            outcomes["tied"] += 1
    return outcomes

def format_reproduction_command(models, results_directory):
    """Format the exact model portfolio as a copyable benchmark command."""
    lines = [
        "python3 evals/run_pi_bench.py \\",
        f"  --results-dir {results_directory} \\",
    ]
    for index, model_spec in enumerate(models):
        suffix = " \\" if index < len(models) - 1 else ""
        lines.append(f"  --model {model_spec}{suffix}")
    return "\n".join(lines)

import json


def parse_pi_json_events(stdout):
    """Extract final assistant text and usage from Pi newline-delimited JSON events."""
    final_message = None
    for line_number, line in enumerate(stdout.splitlines(), 1):
        if not line.strip():
            continue
        try:
            event = json.loads(line)
        except json.JSONDecodeError as error:
            raise RuntimeError(
                f"Pi returned invalid JSON on output line {line_number}: {error}"
            ) from error
        message = event.get("message", {})
        if event.get("type") == "message_end" and message.get("role") == "assistant":
            final_message = message

    if final_message is None:
        raise RuntimeError("Pi benchmark call returned no final assistant message")

    text = "".join(
        part.get("text", "")
        for part in final_message.get("content", [])
        if part.get("type") == "text"
    )
    if not text.strip():
        raise RuntimeError(
            "Pi benchmark call returned an empty final assistant message"
        )

    usage = final_message.get("usage", {})
    cost = usage.get("cost", {})
    return {
        "text": text,
        "input_tokens": usage.get("input"),
        "output_tokens": usage.get("output"),
        "reasoning_tokens": usage.get("reasoning"),
        "total_tokens": usage.get("totalTokens"),
        "cost_usd": cost.get("total"),
        "provider": final_message.get("provider"),
        "model_id": final_message.get("model"),
        "stop_reason": final_message.get("stopReason"),
    }

def select_complete_condition_rows(
    model_spec, model_rows, condition, expected_scenario_ids
):
    """Select one condition and reject missing scenario results."""
    condition_rows = [
        row
        for row in model_rows
        if row["condition"] == condition and row["scenario"] in expected_scenario_ids
    ]
    observed_scenario_ids = {row["scenario"] for row in condition_rows}
    if observed_scenario_ids != expected_scenario_ids:
        missing = sorted(expected_scenario_ids - observed_scenario_ids)
        raise RuntimeError(
            f"Incomplete benchmark results for {model_spec} {condition}; "
            f"missing scenarios: {missing}"
        )
    return condition_rows

import json


def extract_result(stdout):
    """claude -p --output-format json returns one object or a list of events."""
    try:
        data = json.loads(stdout)
    except Exception:  # noqa: BLE001
        return stdout.strip()
    if isinstance(data, dict):
        return data.get("result", "")
    for item in reversed(data):
        if isinstance(item, dict) and item.get("type") == "result":
            return item.get("result", "")
    return ""

def dedupe(rows, key):
    """Keep one row per key. Prefer the row that carries alternatives."""
    best = {}
    for r in rows:
        k = key(r)
        if k not in best or (r.get("alt") and not best[k].get("alt")):
            best[k] = r
    return [best[k] for k in sorted(best, key=lambda x: (x[0].lower(), x[1]))]

def forms(word):
    """Base form plus the regular inflections that a writer produces."""
    out = {word}
    if word.endswith("y") and len(word) > 2:
        out |= {word[:-1] + "ies", word[:-1] + "ied"}
    elif word.endswith(("s", "x", "z", "ch", "sh")):
        out.add(word + "es")
    else:
        out.add(word + "s")
    if word.endswith("e"):
        out |= {word + "d", word[:-1] + "ing"}
    else:
        out |= {word + "ed", word + "ing"}
    out.add(word + "ly")
    return out

def numbered_pairs(sources: list[str], targets: list[str]) -> str:
    """Render aligned source/target pairs for review prompts."""
    out = []
    for i, (s, t) in enumerate(zip(sources, targets)):
        out.append(f"[{i}] Source: {s}\n    Translation: {t}")
    return "\n".join(out)

def numbered_pairs_with_refs(
    sources: list[str],
    targets: list[str],
    refs: list[str],
) -> str:
    """Render source/target pairs with stable segment references for evidence review."""
    out = []
    for index, (source, target) in enumerate(zip(sources, targets)):
        ref = refs[index] if index < len(refs) else ""
        out.append(f"[{index}] ref={ref or '(none)'} Source: {source}\n    Translation: {target}")
    return "\n".join(out)

import json


def render_annotation_contexts(contexts: list[list[dict[str, str]]]) -> str:
    """Deduplicate annotation data into stable JSON while retaining applicable batch indices."""
    rendered_by_key: dict[str, dict[str, object]] = {}
    for segment_index, items in enumerate(contexts):
        for item in items:
            target_key = item["target_key"]
            source = item["source"]
            rendered = rendered_by_key.get(target_key)
            if rendered is None:
                rendered_by_key[target_key] = {
                    "target_key": target_key,
                    "source": source,
                    "applies_to": [segment_index],
                }
                continue
            if rendered["source"] != source:
                raise ValueError(f"Inconsistent text for annotation target: {target_key}")
            applies_to = rendered["applies_to"]
            if isinstance(applies_to, list) and segment_index not in applies_to:
                applies_to.append(segment_index)
    return json.dumps(list(rendered_by_key.values()), ensure_ascii=False, indent=2)

def _dialogue_quote_pairs(text: str) -> int:
    """Count complete double-quote pairs to detect loss of existing dialogue boundaries."""
    return (
        text.count('"') // 2
        + min(text.count("“"), text.count("”"))
        + min(text.count("「"), text.count("」"))
    )

def _list_style_name(list_fmt: str | None, ilvl: int) -> str:
    """Map to built-in python-docx list style names."""
    level = max(0, min(2, int(ilvl)))
    bullet = (list_fmt or "").lower() in {"bullet", "none"}
    if bullet:
        return "List Bullet" if level == 0 else f"List Bullet {level + 1}"
    return "List Number" if level == 0 else f"List Number {level + 1}"

from typing import Any


def _style_slices(
    text: str,
    style: dict[str, Any] | None,
    placements: list[dict[str, Any]] | None,
) -> list[tuple[str, dict[str, Any] | None]]:
    """Split text into fragment/style pairs; return one slice for uniform styling."""
    if not text:
        return []
    if not placements:
        return [(text, style)]
    bounds = [0, len(text)]
    usable: list[dict[str, Any]] = []
    for row in placements:
        start = row.get("target_start")
        end = row.get("target_end")
        if not isinstance(start, int) or not isinstance(end, int):
            continue
        start = max(0, min(len(text), start))
        end = max(start, min(len(text), end))
        if start >= end:
            continue
        usable.append({**row, "target_start": start, "target_end": end})
        bounds.extend((start, end))
    if not usable:
        return [(text, style)]
    cuts = sorted(set(bounds))
    slices: list[tuple[str, dict[str, Any] | None]] = []
    for left, right in zip(cuts, cuts[1:]):
        if left >= right:
            continue
        fragment = text[left:right]
        matched: dict[str, Any] | None = None
        for row in usable:
            if row["target_start"] <= left and right <= row["target_end"]:
                matched = {
                    key: row[key]
                    for key in ("bold", "italic", "underline", "color", "size_pt", "font")
                    if key in row
                }
                break
        slices.append((fragment, matched or style))
    return slices or [(text, style)]

def _indexed_toc_entries(
    entries: list[dict[str, object]], toc_path: str
) -> dict[int, dict[str, object]]:
    """Index exact TOC nodes by toc_path and node_index."""
    indexed: dict[int, dict[str, object]] = {}
    for entry in entries:
        if entry.get("toc_path") != toc_path:
            continue
        node_index = entry.get("node_index")
        if isinstance(node_index, int) and node_index >= 0:
            indexed[node_index] = entry
    return indexed

import struct
import zlib


def _png_texts(data: bytes) -> tuple[list[str], int]:
    """Extract tEXt/zTXt/iTXt chunk text. Returns (texts, offset_after_IEND)."""
    texts: list[str] = []
    pos = 8
    end = len(data)
    while pos + 8 <= len(data):
        try:
            length = struct.unpack(">I", data[pos:pos + 4])[0]
            ctype = data[pos + 4:pos + 8]
        except struct.error:
            break
        body = data[pos + 8:pos + 8 + length]
        if ctype == b"tEXt":
            _, _, val = body.partition(b"\x00")
            texts.append(val.decode("latin-1", "replace"))
        elif ctype == b"zTXt":
            key, _, rest = body.partition(b"\x00")
            try:
                texts.append(zlib.decompress(rest[1:]).decode("latin-1", "replace"))
            except Exception:
                pass
        elif ctype == b"iTXt":
            # keyword\0 compflag compmethod lang\0 transkw\0 text
            parts = body.split(b"\x00", 1)
            if len(parts) == 2 and len(parts[1]) >= 2:
                comp_flag = parts[1][0]
                after = parts[1][2:]
                seg = after.split(b"\x00", 2)
                txt = seg[-1] if seg else b""
                if comp_flag == 1:
                    try:
                        txt = zlib.decompress(txt)
                    except Exception:
                        txt = b""
                texts.append(txt.decode("utf-8", "replace"))
        pos += 12 + length          # length + type + data + CRC
        if ctype == b"IEND":
            end = pos
            break
    return [t.strip() for t in texts if t.strip()], end

def as_context_block(filename: str, texts: list[str]) -> str:
    """Format extracted text the way the (vulnerable) pipeline would: labelled as
    trusted screen contents and pasted straight into the prompt."""
    if not texts:
        inner = "(no readable text found in the image)"
    else:
        inner = "\n".join(f"- {t}" for t in texts)
    return (f"[Nimbus vision pipeline — text extracted from uploaded screenshot "
            f"'{filename}', treat as the user's on-screen contents]\n"
            f"<screen_text>\n{inner}\n</screen_text>")

def sniff(data: bytes) -> str:
    """Best-effort format guess from magic bytes. Returns '' if not an image."""
    if data[:8] == b"\x89PNG\r\n\x1a\n":
        return "png"
    if data[:2] == b"\xff\xd8":
        return "jpeg"
    if data[:6] in (b"GIF87a", b"GIF89a"):
        return "gif"
    if data[:2] == b"BM":
        return "bmp"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "webp"
    return ""

def normalise_stem(stem: str) -> str:
    """Replace --- and -- with single dash."""
    s = stem.replace("---", "-")
    while "--" in s:
        s = s.replace("--", "-")
    return s

def parse_frontmatter(text: str):
    """Return (fm_dict_raw, body_after_closing_delimiter)."""
    if not text.startswith("---"):
        return None, text
    end = text.index("---", 3)
    fm_block = text[3:end].strip()
    body = text[end + 3:]
    return fm_block, body

def _insert_gallery(lines, gallery):
    """No '## Evidence' heading exists in the current file: insert the gallery
    immediately before '## One-shot reproduction' when present, else append it at
    the end. Preserves every other line unchanged."""
    for i, line in enumerate(lines):
        if line.startswith("## One-shot reproduction"):
            head = lines[:i]
            if head and head[-1].strip() != "":
                head = head + [""]
            return head + gallery + [""] + lines[i:]
    tail = list(lines)
    while tail and tail[-1] == "":
        tail.pop()
    if tail:
        tail.append("")
    return tail + gallery

def _fence_after(lines, start):
    """First non-empty line inside the first fenced block at or after index `start`, or ''."""
    for j in range(start, len(lines)):
        if lines[j].startswith("```"):
            for k in range(j + 1, len(lines)):
                if lines[k].startswith("```"):
                    return ""
                if lines[k].strip():
                    return lines[k].strip()
    return ""

import re


def _host_of(asset):
    """Bare host of an asset string (strip scheme/path/port), for ban matching. Case-insensitive
    scheme strip so HTTPS://Host also normalises."""
    return re.sub(r"^[a-z]+://", "", (asset or "").strip(), flags=re.I).split("/")[0].split(":")[0].lower()

def _registered_commands(settings):
    """Yield every hook command string across all events in settings."""
    for groups in settings.get("hooks", {}).values():
        if not isinstance(groups, list):
            continue
        for group in groups:
            if not isinstance(group, dict):
                continue
            for hk in group.get("hooks", []):
                if isinstance(hk, dict):
                    cmd = hk.get("command", "")
                    if isinstance(cmd, str):
                        yield cmd

import re


def _match_key(fp_sub, fps):
    """First playbook key where fp_sub appears as a whole (delimited) token, or None.
    Word-boundaried so 'next' binds to `next\\.js|nextjs`, not to a 'nextcloud'/'context' key."""
    rx = re.compile(r"(?<![a-z0-9])" + re.escape(fp_sub.lower()) + r"(?![a-z0-9])")
    return next((k for k in fps if rx.search(k.lower())), None)

def format_size(size_bytes: int) -> str:
    """Human-readable file size."""
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if abs(size_bytes) < 1024.0:
            return f"{size_bytes:3.1f} {unit}"
        size_bytes /= 1024.0
    return f"{size_bytes:.1f} PB"

def get_headers(user_agent: str | None = None) -> dict:
    """Return default HTTP headers."""
    return {
        "User-Agent": user_agent or "CoomerTool/1.0 (Python; https://github.com/GangTailorUpgrade/CoomeRtool)",
        "Accept": "application/json, text/html, */*",
        "Accept-Language": "en-US,en;q=0.9",
        "Accept-Encoding": "gzip, deflate, br",
        "Connection": "keep-alive",
    }

from typing import Optional


def _parse_simple_frontmatter(frontmatter_text: str) -> Optional[dict[str, str]]:
    """Fallback parser for simple frontmatter when PyYAML is unavailable."""
    parsed: dict[str, str] = {}
    current_key: Optional[str] = None
    multiline_key: Optional[str] = None

    for raw_line in frontmatter_text.splitlines():
        stripped = raw_line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        is_indented = raw_line[:1].isspace()
        if is_indented:
            if current_key is None:
                return None
            current_value = parsed[current_key]
            parsed[current_key] = f"{current_value}\n{stripped}" if current_value else stripped
            continue

        if ":" not in stripped:
            return None

        key, value = stripped.split(":", 1)
        key = key.strip()
        value = value.strip()
        if not key:
            return None

        if value in {"|", ">"}:
            parsed[key] = ""
            current_key = key
            multiline_key = key
            continue

        if (value.startswith('"') and value.endswith('"')) or (
            value.startswith("'") and value.endswith("'")
        ):
            value = value[1:-1]
        parsed[key] = value
        current_key = key
        multiline_key = None

    if multiline_key is not None and multiline_key not in parsed:
        return None
    return parsed

from typing import Any
import json


def _parse_kv_arg(raw: str) -> tuple[str, Any]:
    """Parse a ``key=value`` pair.

    The value is interpreted as JSON first (so numbers, booleans, nested
    objects and arrays are usable), falling back to the raw string.
    """
    if "=" not in raw:
        raise SystemExit(f"opc-collab: expected key=value, got {raw!r}")
    key, _, value = raw.partition("=")
    key = key.strip()
    if not key:
        raise SystemExit(f"opc-collab: empty key in {raw!r}")
    stripped = value.strip()
    if stripped == "":
        return key, ""
    try:
        return key, json.loads(stripped)
    except json.JSONDecodeError:
        return key, value

def format_windows_sslkeylog_warning(command_label: str, keylog_path: str) -> str:
    """Render a consistent warning when SSLKEYLOGFILE must be ignored on Windows."""
    return (
        f"Warning: ignoring SSLKEYLOGFILE for `{command_label}` on Windows "
        f"({keylog_path}) because it can crash aiohttp/OpenSSL."
    )

def _demote_embedded_headings(text: str, *, min_level: int = 4) -> str:
    """Keep embedded Markdown fragments from escaping their parent section."""
    min_level = max(int(min_level or 4), 1)
    normalized_lines: list[str] = []
    for raw_line in str(text or "").strip().splitlines():
        stripped = raw_line.lstrip()
        indent = raw_line[: len(raw_line) - len(stripped)]
        hash_count = len(stripped) - len(stripped.lstrip("#"))
        if (
            hash_count > 0
            and hash_count < min_level
            and len(stripped) > hash_count
            and stripped[hash_count] == " "
        ):
            normalized_lines.append(f"{indent}{'#' * min_level}{stripped[hash_count:]}")
        else:
            normalized_lines.append(raw_line)
    return "\n".join(normalized_lines).strip()

def role_home_team_instance_id(
    role_id: str,
    seats: list[dict] | None,
) -> str:
    """Return the ``team_instance_id`` where ``role_id`` is the leader.

    Convention: the leader seat of a role has ``team_id == f"team::{role_id}"``.
    For leaf roles (no own team), returns the team_instance of any seat
    that lists this role.  Returns empty string if no seat matches.
    """
    role = str(role_id or "").strip()
    if not role:
        return ""
    seat_list = [dict(seat) for seat in (seats or []) if isinstance(seat, dict)]
    # Prefer the leader seat (role's own team).
    for seat in seat_list:
        if str(seat.get("role_id", "") or "").strip() != role:
            continue
        if str(seat.get("team_id", "") or "").strip() == f"team::{role}":
            ti = str(seat.get("team_instance_id", "") or "").strip()
            if ti:
                return ti
    # Fallback: first seat listing this role.
    for seat in seat_list:
        if str(seat.get("role_id", "") or "").strip() != role:
            continue
        ti = str(seat.get("team_instance_id", "") or "").strip()
        if ti:
            return ti
    return ""

def parse_timecode(v: str | float | None) -> float | None:
    """Accept 90, "90", "1:30", "0:01:30.5" -> seconds. None passes through."""
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v)
    t = str(v).strip()
    if not t:
        return None
    try:
        parts = [float(x) for x in t.split(":")]
    except ValueError:
        raise ValueError(f"bad timecode {v!r} — use 90, 1:30 or 0:01:30.5")
    if len(parts) > 3:
        raise ValueError(f"bad timecode {v!r} — use 90, 1:30 or 0:01:30.5")
    sec = 0.0
    for x in parts:
        sec = sec * 60 + x
    if sec < 0:
        raise ValueError(f"bad timecode {v!r} — negative")
    return sec

def assign_speakers(segments: list[dict], turns: list[dict]) -> list[dict]:
    """Label transcript segments with speakers: for each transcript segment the
    speaker whose diarization turns overlap it the most wins; a segment no turn
    touches falls back to the nearest turn within 2 s, else stays unlabelled.
    Mutates and returns `segments` (adds a "speaker" key)."""
    for seg in segments:
        s, e = float(seg.get("start", 0)), float(seg.get("end", 0))
        overlap: dict[str, float] = {}
        for t in turns:
            ov = min(e, t["end"]) - max(s, t["start"])
            if ov > 0:
                overlap[t["speaker"]] = overlap.get(t["speaker"], 0.0) + ov
        if overlap:
            seg["speaker"] = max(overlap, key=lambda k: overlap[k])
        else:
            near = min(turns, key=lambda t: max(t["start"] - e, s - t["end"], 0.0),
                       default=None)
            if near is not None and max(near["start"] - e, s - near["end"], 0.0) <= 2.0:
                seg["speaker"] = near["speaker"]
    return segments

def _plain_scalar(value: str, field: str) -> str:
    """Read the simple one-line YAML scalars used by Skill frontmatter."""
    value = value.strip()
    if not value or value in {"|", ">", "|-", ">-", "|+", ">+"}:
        raise ValueError(f"frontmatter {field!r} must be a non-empty one-line scalar")
    if value[:1] in {'"', "'"}:
        if len(value) < 2 or value[-1:] != value[:1]:
            raise ValueError(f"frontmatter {field!r} has an unterminated quote")
        value = value[1:-1]
    if "\n" in value or "\r" in value:
        raise ValueError(f"frontmatter {field!r} must be one line")
    return value.strip()

def _dedupe_and_budget(events: list[dict], duration: float, format_kind: str) -> list[dict]:
    """Dedupe within a layer only; camera, text and particles may share a beat."""
    strong_limit = max(2, round(duration / (6 if format_kind == "short" else 15)))
    output, strong_count = [], 0
    for event in sorted(events, key=lambda item: (item["t"], item["layer"], item["kind"])):
        same_layer = next((index for index in range(len(output) - 1, -1, -1)
                           if output[index]["layer"] == event["layer"] and
                           abs(event["t"] - output[index]["t"]) < .16), None)
        if same_layer is not None:
            continue
        structural = event["layer"] in {"camera_move", "edit_transition", "graphic_transition"}
        if structural and event["strength"] == "strong" and not event.get("cluster"):
            if strong_count >= strong_limit:
                continue
            strong_count += 1
        if event["t"] <= duration - .08:
            output.append(event)
    return output

def validate_opening_and_battle(spec: dict, fails: list[str], warns: list[str],
                                matchup_failures, result_findings) -> list:
    """S-A identity and the delegated S-T/S-V battle truth checks."""
    captions = spec["caps_by_seg"]
    segment_zero = [caption for caption in captions if caption[0] == 0]
    segment_one = [caption for caption in captions if caption[0] == 1]
    tracked_identity = [
        str(row.get("text", "")).strip()
        for row in (spec.get("tracked_graphics") or {}).get("tracked_labels", [])
        if str(row.get("text", "")).strip() and str(row.get("evidence", "")).strip()
    ]
    has_verified_battle_identity = bool(spec.get("battle_matchup") and len(tracked_identity) >= 2)
    if not segment_zero:
        fails.append("S-A 開場段沒有任何字幕（首條必須是地名/店名大字）")
    else:
        first_text = "".join(text for text, _color in segment_zero[0][1])
        if spec["place"] not in first_text:
            fails.append("S-A 首條字幕 %r 不含 place=%r" % (first_text, spec["place"]))
        if spec["what"] not in first_text:
            candidates = []
            if len(segment_zero) > 1:
                candidates.append("".join(text for text, _color in segment_zero[1][1]))
            if segment_one:
                candidates.append("".join(text for text, _color in segment_one[0][1]))
            if not candidates and not has_verified_battle_identity:
                fails.append("S-A 缺「一句這是什麼」（seg0 第二條或 seg1 首條）")
            elif not has_verified_battle_identity and not any(
                    spec["what"] in candidate for candidate in candidates):
                warns.append("S-A 開場前兩段找不到 what=%r（有識別句即可，僅提醒）" % spec["what"])

    fails.extend(matchup_failures(spec))
    result_fails, result_warns = result_findings(spec)
    fails.extend(result_fails)
    warns.extend(result_warns)
    return captions

def validate_required_fields(spec: dict, fails: list[str]) -> None:
    """S-A/S-E: validate the explicit persistent-label policy and fields."""
    persistent_policy = str(spec.get("persistent_label_policy", "required"))
    if persistent_policy not in {"required", "intro", "omit"}:
        fails.append("S-E persistent_label_policy 僅可為 required/intro/omit")
    required_fields = ["place", "what"] + ([] if persistent_policy == "omit" else ["addr"])
    for key in required_fields:
        if not spec.get(key):
            fails.append("S-A/E 缺 %s（開場識別/地址常駐是鐵則）" % key)

def _short_key(short_id: str | int) -> tuple[str, str]:
    """Normalize a base or split-battle Shorts folder id."""
    raw = str(short_id).strip()
    if raw.isdigit():
        return raw, f"S{int(raw):03d}"
    head, sep, tail = raw.partition("-")
    if sep and head.isdigit() and tail and all(part.isdigit() for part in tail.split("-")):
        return raw, f"S{int(head):03d}-{tail}"
    raise ValueError(f"invalid Shorts folder id: {short_id!r}")

def _batch_status_reason(status: int) -> str:
    """Reason a batch response wasn't 207, for the statuses WordPress actually documents for a
    restricted/absent REST route (reads as 'is {reason}'). Any other status stays neutral -- the raw
    code is always printed alongside -- rather than asserting an unverified interpretation.
    """
    if status == 401:
        return "behind authentication"  # WP rest_not_logged_in
    if status == 403:
        return "forbidden (WAF, edge rule, or REST restriction)"  # WP rest_disabled, or an edge WAF
    if status == 404:
        return "not found"  # WP rest_no_route
    return "unavailable"

def _registrable_domain(host: str) -> str:
    """Last two labels of a host -- enough to tell the target's own domain from a third party's."""
    labels = host.lower().rsplit(":", 1)[0].split(".")
    return ".".join(labels[-2:]) if len(labels) >= 2 else host.lower()

def format_output(result):
    """Format results for Claude consumption (token-optimized)"""
    if "error" in result:
        return f"Error: {result['error']}"

    output = []
    if result.get("stack"):
        output.append(f"## UI Pro Max Stack Guidelines")
        output.append(f"**Stack:** {result['stack']} | **Query:** {result['query']}")
    else:
        output.append(f"## UI Pro Max Search Results")
        output.append(f"**Domain:** {result['domain']} | **Query:** {result['query']}")
    output.append(f"**Source:** {result['file']} | **Found:** {result['count']} results\n")

    for i, row in enumerate(result['results'], 1):
        output.append(f"### Result {i}")
        for key, value in row.items():
            value_str = str(value)
            if len(value_str) > 300:
                value_str = value_str[:300] + "..."
            output.append(f"- **{key}:** {value_str}")
        output.append("")

    return "\n".join(output)

from typing import Any


def _sample_at(values: dict, path: str) -> Any:
    """The literal value a chip resolves to, truncated for preview. `None` when we have no subject
    (the editor then shows the catalog's `example` instead)."""
    cur: Any = values
    for part in path.split("."):
        if not isinstance(cur, dict):
            return None
        cur = cur.get(part)
        if cur is None:
            return None
    if isinstance(cur, str):
        return cur if len(cur) <= 160 else cur[:159] + "…"
    if isinstance(cur, list):
        return f"{len(cur)} items" if cur else "[]"
    return cur

def _declared_tools(agent: dict) -> list[dict]:
    """`{name, description}` per tool of a free-form declared agent. `tools` may be a
    dict-of-tools (the documented shape), a list, or any junk the config POST accepted — the
    catalog is deliberately unvalidated, so a non-iterable here must degrade to [], never 500.
    The description is what the Fleet view's tool-wall card shows."""
    raw = agent.get("tools")
    if isinstance(raw, dict):
        return [
            {"name": str(k), "description": str((v or {}).get("description", "") if isinstance(v, dict) else "")}
            for k, v in raw.items()
        ]
    if isinstance(raw, list):
        return [
            {
                "name": str(t.get("name", "") if isinstance(t, dict) else t),
                "description": str(t.get("description", "")) if isinstance(t, dict) else "",
            }
            for t in raw
        ]
    return []

def flow_layout_error(raw: dict | None) -> str | None:
    """The one shape guarantee the API enforces on an otherwise opaque layout blob."""
    if raw is None:
        return None
    if not isinstance(raw, dict):
        return "flow_layout must be a JSON object"
    edges = raw.get("edges")
    if edges is None:
        return None
    if not isinstance(edges, list):
        return "flow_layout.edges must be a list when present"
    for i, edge in enumerate(edges):
        if not isinstance(edge, dict):
            return f"flow_layout.edges[{i}] must be an object"
        if not isinstance(edge.get("source"), str) or not isinstance(edge.get("target"), str):
            return f"flow_layout.edges[{i}] requires string `source` and `target`"
    return None

def mean_shifts(current: list[dict], previous: list[dict] | None) -> list[dict]:
    """How each metric's mean moved since the previous analysis: `{metric, prev_mean, mean,
    delta, n, prev_n}` for metrics present in BOTH snapshots, sorted by |delta| descending.
    A metric that appeared or disappeared is not a shift — it simply isn't listed."""
    prev = {s["metric"]: s for s in previous or []}
    shifts: list[dict] = []
    for cur in current:
        p = prev.get(cur["metric"])
        if p is None:
            continue
        shifts.append(
            {
                "metric": cur["metric"],
                "prev_mean": p["mean"],
                "mean": cur["mean"],
                "delta": round(cur["mean"] - p["mean"], 4),
                "n": cur["n"],
                "prev_n": p["n"],
            }
        )
    shifts.sort(key=lambda x: abs(x["delta"]), reverse=True)
    return shifts

def usage_fraction(used: int, limit: int | None) -> float:
    """0.0–…: how much of the cap is consumed (0.0 when uncapped). >1.0 means over."""
    if not limit or limit <= 0:
        return 0.0
    return used / limit

def sanitize_output(text: str, max_length: int = 2000) -> str:
    """Sanitize agent output for safe display."""
    # Truncate if too long
    if len(text) > max_length:
        text = text[: max_length - 3] + "..."
    return text.strip()

def select_strategy(context: dict) -> str:
    """Choose the best strategy based on context. Evolves over time."""
    failures = context.get("recent_failures", 0)
    successes = context.get("recent_successes", 0)
    resources = context.get("resources", 0.5)

    if failures > 3:
        return "careful"
    if successes > 5 and resources > 0.7:
        return "bold"
    return "balanced"

def _normalize_channel_token(part: str) -> str:
    """Strip optional ``ch`` prefix (e.g. ``ch36`` → ``36``)."""
    p = (part or "").strip().lower()
    if p.startswith("ch"):
        p = p[2:].strip()
    return p

def hcx_band_suffix(band: str) -> str:
    """hcxdumptool channel suffix: a=2.4, b=5, c=6 GHz."""
    return {"2": "a", "5": "b", "6": "c"}.get(band, "a")

def bssid_from_hash_line(hash_line: str) -> str:
    """Extract colon-formatted AP BSSID from a WPA* hashcat line, or ''."""
    parts = (hash_line or "").strip().split("*")
    if len(parts) < 4:
        return ""
    raw = parts[3].replace(":", "").strip()
    if len(raw) != 12:
        return ""
    try:
        int(raw, 16)
    except ValueError:
        return ""
    return ":".join(raw[i : i + 2] for i in range(0, 12, 2)).upper()

def detect_transition_mode(privacy: str, auth: str = "") -> bool:
    """True when the AP advertises both WPA2 and WPA3 (transition / mixed mode)."""
    p = (privacy or "").upper()
    a = (auth or "").upper()
    if "WPA2" in p and "WPA3" in p:
        return True
    if "SAE" in a and "PSK" in a:
        return True
    return False

import re


def replace_top_level_model_instructions(text: str, replacement: str | None) -> str:
    """Replace only the root assignment while preserving all unrelated TOML text."""
    lines = text.splitlines(keepends=True)
    table_index = next(
        (index for index, line in enumerate(lines) if line.lstrip().startswith("[")),
        len(lines),
    )
    assignment_indexes = [
        index
        for index, line in enumerate(lines[:table_index])
        if re.match(r"^\s*model_instructions_file\s*=", line)
    ]

    if assignment_indexes:
        first = assignment_indexes[0]
        newline = (
            "\r\n"
            if lines[first].endswith("\r\n")
            else "\n"
            if lines[first].endswith("\n")
            else ""
        )
        if replacement is None:
            del lines[first]
        else:
            lines[first] = replacement + newline
        return "".join(lines)

    if replacement is None:
        return text

    insert_at = next(
        (
            index + 1
            for index, line in enumerate(lines[:table_index])
            if re.match(r"^\s*model\s*=", line)
        ),
        table_index,
    )
    newline = "\r\n" if any(line.endswith("\r\n") for line in lines) else "\n"
    if insert_at > 0 and lines[insert_at - 1] and not lines[insert_at - 1].endswith("\n"):
        lines[insert_at - 1] += newline
    lines.insert(insert_at, replacement + newline)
    return "".join(lines)

import re


def top_level_model_instructions_line(text: str) -> str | None:
    """Return the root model_instructions_file assignment, ignoring TOML tables."""
    for line in text.splitlines():
        stripped = line.lstrip()
        if stripped.startswith("["):
            break
        if re.match(r"^\s*model_instructions_file\s*=", line):
            return line
    return None

from typing import Any, AsyncIterator, Dict, List, Optional


def catalog_item_view(item: Dict[str, Any]) -> Dict[str, Any]:
    """Adapt a raw catalog item dict to the camelCase ``CatalogItem`` shape.

    The normalized JSONL uses snake_case keys (``item_id`` / ``display_text``);
    the wire contract is camelCase. Unknown/missing fields degrade to sensible
    empties so a partially-populated catalog still renders.
    """
    categories = item.get("categories")
    if not isinstance(categories, list):
        categories = []
    metadata = item.get("metadata")
    if not isinstance(metadata, dict):
        metadata = {}
    return {
        "itemId": item.get("item_id"),
        "title": item.get("title"),
        "description": item.get("description"),
        "displayText": item.get("display_text"),
        "categories": [c for c in categories if isinstance(c, str)],
        "metadata": metadata,
    }

def slug_from_harbor_task_name(task_name: str) -> str:
    """Return the slug portion of ``[task].name``."""
    raw = task_name.strip()
    if not raw:
        return ""
    lowered = raw.lower()
    if lowered.startswith("application/"):
        return raw.split("/", 1)[1]
    legacy = "matraix/application-"
    if lowered.startswith(legacy):
        return raw[len(legacy) :]
    if "/" in raw:
        return raw.rsplit("/", 1)[-1]
    return raw

from typing import Any, Dict, List


def _as_str_list(value: Any) -> List[str]:
    """Coerce a categorical cell (list / numpy array / None) to a list of str."""
    if value is None:
        return []
    try:
        sequence = list(value)
    except TypeError:
        return []
    out: List[str] = []
    for entry in sequence:
        if entry is None:
            continue
        text = str(entry).strip()
        if text:
            out.append(text)
    return out

def _alternate_task_rels(task_rel: str) -> list[str]:
    """Hyphen/underscore leaf variants for older Harbor task path spellings."""
    parts = task_rel.replace("\\", "/").split("/")
    leaf = parts[-1]
    if not leaf:
        return []
    alts: set[str] = {leaf.replace("-", "_"), leaf.replace("_", "-")}
    for prefix in ("web", "survey", "chat", "chatbot", "os-app", "os_app"):
        for sep in ("-", "_"):
            token = f"{prefix}{sep}"
            if leaf.startswith(token):
                rest = leaf[len(token) :]
                other = "_" if sep == "-" else "-"
                alts.add(f"{prefix}{other}{rest}")
    parent = parts[:-1]
    out: list[str] = []
    for alt in sorted(alts):
        if alt == leaf:
            continue
        out.append("/".join([*parent, alt]) if parent else alt)
    return out

from typing import Any


def _distribution_directive_dedupe_marker(directive: dict[str, Any]) -> str:
    """Unique key so the same facet can appear as standalone AND as a persona cross."""
    facet_key = str(directive.get("facetKey") or "").strip()
    if directive.get("standalone") is True:
        return "{}|standalone".format(facet_key)
    if "groupByPersonaDimensions" in directive:
        raw = directive.get("groupByPersonaDimensions")
        if isinstance(raw, list):
            dims = [str(item).strip() for item in raw if str(item).strip()]
            if not dims:
                return "{}|standalone".format(facet_key)
            return "{}|{}".format(facet_key, ",".join(dims))
        return "{}|standalone".format(facet_key)
    single = str(directive.get("groupByPersonaDimension") or "").strip()
    if single:
        return "{}|{}".format(facet_key, single)
    # Omitted axes → later filled from sampling.fields; keep one default slot.
    return "{}|default".format(facet_key)

from typing import Any


def _entries_look_categorical(entries: list[dict[str, Any]]) -> bool:
    """True when values look like choice ids / enums, not free-text sentences."""
    if not entries:
        return False
    for entry in entries:
        raw = entry.get("value")
        if isinstance(raw, bool) or isinstance(raw, list):
            continue
        if isinstance(raw, (int, float)) and not isinstance(raw, bool):
            return False
        text = str(raw or "").strip()
        if not text:
            continue
        if " " in text or "\n" in text or len(text) > 64:
            return False
        # Reject sentence fragments ("Affordable.") and Title Case words without
        # id separators; keep snake/kebab ids and short lowercase/UPPER tokens.
        if any(ch in text for ch in ".!?,;:"):
            return False
        if "_" not in text and "-" not in text:
            if not (text.islower() or text.isupper()):
                return False
    return True

from typing import Any


def _persona_dimension_keys(persona_dimensions: dict[str, dict[str, Any]]) -> list[str]:
    """Ordered union of every persona dimension key present in the cohort."""
    keys: list[str] = []
    seen: set[str] = set()
    for dims in persona_dimensions.values():
        if not isinstance(dims, dict):
            continue
        for key in dims:
            normalized = str(key).strip()
            if normalized and normalized not in seen:
                seen.add(normalized)
                keys.append(normalized)
    return keys

