def circles_from_rect(left: float, top: float, width: float, height: float) -> list[list[float]]:
    """Generate the three equal circles inscribed in a visible content rect."""
    left, top = float(left), float(top)
    width, height = max(0.0, float(width)), max(0.0, float(height))
    radius = min(width, height) / 2.0
    cx, cy = left + width / 2.0, top + height / 2.0
    if width >= height:
        return [[left + radius, cy, radius], [cx, cy, radius],
                [left + width - radius, cy, radius]]
    return [[cx, top + radius, radius], [cx, cy, radius],
            [cx, top + height - radius, radius]]

def _insert_at_template_anchor(
    target: list[dict], node: dict, template: list[dict], template_index: int
) -> None:
    """Insert beside the nearest template sibling without reordering user nodes."""
    target_ids = [str(candidate.get("id") or "") for candidate in target]
    for sibling in reversed(template[:template_index]):
        sibling_id = str(sibling.get("id") or "")
        if sibling_id in target_ids:
            target.insert(target_ids.index(sibling_id) + 1, node)
            return
    for sibling in template[template_index + 1 :]:
        sibling_id = str(sibling.get("id") or "")
        if sibling_id in target_ids:
            target.insert(target_ids.index(sibling_id), node)
            return
    target.append(node)

from typing import Any


def _num_tokens(input_ids: Any) -> int:
    """Row count of a token tensor. ``numel`` is metadata: no host sync.

    Never guesses: a 0 here would make any non-empty placeholder count look
    like a full-image batch.
    """
    if hasattr(input_ids, "numel"):
        return int(input_ids.numel())
    try:
        return len(input_ids)
    except TypeError as exc:
        raise TypeError(
            f"Vision-Exp cannot size input_ids of type {type(input_ids).__name__}"
        ) from exc

from collections.abc import Callable, Sequence


def infer_dspark_num_draft_layers(weight_names: Sequence[str]) -> int | None:
    """Infer how many DSpark draft stages are present in a checkpoint.

    The DeepSeek-V4-Flash-DSpark release stores the DSpark draft stages under
    the historical `mtp.N.*` namespace. Unlike regular MTP, the HF config still
    reports `num_nextn_predict_layers=1`, so the weight map is the reliable
    source for the DSpark draft depth.
    """

    layer_ids: set[int] = set()
    for name in weight_names:
        if not name.startswith("mtp."):
            continue
        parts = name.split(".", 2)
        if len(parts) < 3:
            continue
        try:
            layer_ids.add(int(parts[1]))
        except ValueError:
            continue

    if not layer_ids:
        return None
    expected = set(range(max(layer_ids) + 1))
    if layer_ids != expected:
        raise ValueError(
            "DSpark MTP namespace must be contiguous from mtp.0; "
            f"found {sorted(layer_ids)}"
        )
    return max(layer_ids) + 1

from collections.abc import Callable, Sequence


def speculative_acceptance_confidence(
    draft_probs: Sequence[float],
    target_probs: Sequence[float],
) -> float:
    """Return the exact one-step speculative acceptance probability.

    For normalized draft distribution q and target distribution p, the expected
    acceptance probability is sum_x min(p(x), q(x)), equivalently
    1 - TV(p, q).
    """

    if len(draft_probs) != len(target_probs):
        raise ValueError(
            "draft_probs and target_probs must have the same vocabulary size"
        )
    if len(draft_probs) == 0:
        raise ValueError("probability vectors must not be empty")

    draft_total = sum(float(prob) for prob in draft_probs)
    target_total = sum(float(prob) for prob in target_probs)
    if draft_total <= 0.0 or target_total <= 0.0:
        raise ValueError("probability vectors must have positive total mass")

    draft = [float(prob) / draft_total for prob in draft_probs]
    target = [float(prob) / target_total for prob in target_probs]
    if any(prob < 0.0 for prob in (*draft, *target)):
        raise ValueError("probabilities must be non-negative")

    return sum(
        min(draft_prob, target_prob)
        for draft_prob, target_prob in zip(draft, target, strict=True)
    )

def _mg_head_partitions(heads: int, hpb: int = 16) -> tuple[tuple[int, int, int], ...]:
    """Return ``(mg_n_hg, active_heads, head_offset)`` partitions for 8-aligned heads."""
    heads = int(heads)
    hpb = int(hpb)
    if heads <= 0 or heads % (hpb // 2) != 0:
        return ()

    parts: list[tuple[int, int, int]] = []
    paired_width = 2 * hpb
    paired_heads = (heads // paired_width) * paired_width
    if paired_heads:
        parts.append((2, paired_heads, 0))

    offset = paired_heads
    rem = heads - paired_heads
    if rem >= hpb:
        parts.append((1, hpb, offset))
        offset += hpb
        rem -= hpb
    if rem:
        parts.append((1, rem, offset))
    return tuple(parts)

def find_silences(words: list[dict], start: float, end: float, threshold: float = 0.4) -> list[tuple[float, float]]:
    """Find gaps >= threshold seconds inside [start, end] between kept tokens."""
    gaps: list[tuple[float, float]] = []
    prev_end = start
    for w in words:
        if w.get("type") == "spacing":
            continue
        ws = max(start, w.get("start", start))
        if ws - prev_end >= threshold:
            gaps.append((prev_end, ws))
        prev_end = max(prev_end, w.get("end", ws))
    if end - prev_end >= threshold:
        gaps.append((prev_end, end))
    return gaps

def _resolve_topic_id(client, competition: str, writeup_slug: str) -> int:
    """Map a writeup slug to its forum topic id via the competition leaderboard."""
    competition_info = client.post(
        "competitions.CompetitionService/GetCompetition",
        {"competitionName": competition},
    )
    competition_id = competition_info.get("id") or (
        competition_info.get("competition") or {}
    ).get("id")
    if not competition_id:
        raise RuntimeError(f"Could not resolve competition id for '{competition}'.")

    board = client.post(
        "competitions.LeaderboardService/GetLeaderboard",
        {"competitionId": competition_id},
    )
    for team in board.get("teams") or []:
        url = team.get("solutionWriteUpUrl") or ""
        topic_id = team.get("writeUpForumTopicId")
        if topic_id and url.rstrip("/").endswith("/" + writeup_slug):
            return topic_id

    raise RuntimeError(
        f"Could not find writeup '{writeup_slug}' in the leaderboard for "
        f"'{competition}'. The writeup may be unlisted or removed."
    )

from typing import Any
import re


def parse_public_score(value: Any) -> float | None:
    """Parse a leaderboard score string into a float, or None if not numeric."""
    if value is None:
        return None
    text = str(value).strip()
    if not text or text.lower() in {"-", "na", "n/a", "nan", "none", "null"}:
        return None
    match = re.search(r"[-+]?\d[\d,]*(?:\.\d+)?(?:[eE][-+]?\d+)?", text)
    if not match:
        return None
    try:
        return float(match.group(0).replace(",", ""))
    except ValueError:
        return None

