def competition_slug(value: str) -> str:
    """Extract a Kaggle competition slug from a slug or competition URL."""
    match = re.search(r"kaggle\.com/competitions/([^/?#]+)", value)
    return match.group(1) if match else value.strip().strip("/")

import re


def kernel_ref(value: str) -> str:
    """Extract owner/kernel-slug from a Kaggle code URL or return a ref as-is."""
    match = re.search(r"kaggle\.com/code/([^/?#]+)/([^/?#]+)", value)
    if match:
        return f"{match.group(1)}/{match.group(2)}"
    return value.strip()

def weighted_tag_similarity(left: set[str], right: set[str]) -> float:
    """Weighted-Jaccard proxy for result diversification."""
    if not left or not right:
        return 0.0
    important = {"subject_type", "visual_style", "composition", "lighting", "color_palette", "mood", "scene"}
    union = left | right
    intersection = left & right
    weight = lambda tag: 2.0 if tag.partition(":")[0] in important else 1.0
    return sum(weight(tag) for tag in intersection) / sum(weight(tag) for tag in union)

from typing import Any, Iterable, Sequence


def merged_related_hits(tiers: list[list[dict[str, Any]]], exact_ids: set[str]) -> list[dict[str, Any]]:
    """Merge independent one-facet tiers without favoring config order."""
    best_by_id: dict[str, dict[str, Any]] = {}
    for hits in tiers:
        for item in hits:
            tweet_id = str(item["tweet_id"])
            if tweet_id in exact_ids:
                continue
            existing = best_by_id.get(tweet_id)
            if existing is None or float(item["score"]) > float(existing["score"]):
                best_by_id[tweet_id] = item
    return sorted(
        best_by_id.values(),
        key=lambda item: (-float(item["score"]), str(item["tweet_id"])),
    )

import json
import re


def extract_json(text: str):
    """Return the last JSON object found in agent output, or None.

    Agents wrap answers in prose/fences and sometimes echo the schema first,
    so we collect every decodable object and keep the last one.
    """
    text = text[-100_000:]  # the answer is at the end; don't O(n^2)-scan huge CLI logs
    candidates = []
    for m in re.finditer(r"```(?:json)?\s*(\{.*?\})\s*```", text, re.S):
        candidates.append(m.group(1))
    decoder = json.JSONDecoder()
    i = 0
    while True:
        i = text.find("{", i)
        if i == -1:
            break
        try:
            obj, end = decoder.raw_decode(text[i:])
            if isinstance(obj, dict):
                candidates.append(text[i:i + end])
                i += end
                continue
        except ValueError:
            pass
        i += 1
    for cand in reversed(candidates):
        try:
            obj = json.loads(cand)
            if isinstance(obj, dict):
                return obj
        except ValueError:
            continue
    return None

def unit_price(qty, base=2.00):
    """Bulk discount: 10% off for orders of 100 or more units (see README)."""
    if qty >= 100:
        return round(base * 0.90, 2)
    return base

def convert(x):
    """Scale-and-round helper. Rounds half-up to 2 dp (see README)."""
    if x < -100 or x > 100:
        raise ValueError("out of range")
    return round(x, 2)

def _coerce(text, like):
    """An env-var string, shaped like the default it overrides."""
    if isinstance(like, bool):
        return text.strip().lower() in ("1", "true", "yes", "on")
    if isinstance(like, (int, float)):
        try:
            return type(like)(text)
        except ValueError:
            return like
    return text

import re


def parse_css(text: str) -> dict:
    """`.cls, text { k: v }` -> {selector: {k: v}}. Enough for the class/tag styling these figures use."""
    rules = {}
    for sel, body in re.findall(r"([^{}]+)\{([^{}]*)\}", re.sub(r"/\*.*?\*/", "", text or "", flags=re.S)):
        decls = {}
        for kv in body.split(";"):
            if ":" in kv:
                k, v = kv.split(":", 1)
                decls[k.strip().lower()] = v.strip()
        for s in sel.split(","):
            s = s.strip()
            if s:
                rules.setdefault(s, {}).update(decls)
    return rules

def four_part_version(version: str) -> str | None:
    """Windows assemblyIdentity requires four numeric components."""
    parts = version.split(".")
    if not parts or not all(p.isdigit() for p in parts):
        return None
    while len(parts) < 4:
        parts.append("0")
    return ".".join(parts[:4])

from typing import TYPE_CHECKING, Any, cast


def file_info_to_dict(info: Any) -> dict[str, Any]:
    """Coerce a ``FileInfo`` TypedDict into a JSON-friendly dict."""
    if isinstance(info, dict):
        path = info.get("path")
        is_dir = info.get("is_dir")
        size = info.get("size")
        modified_at = info.get("modified_at")
    else:
        path = getattr(info, "path", None)
        is_dir = getattr(info, "is_dir", None)
        size = getattr(info, "size", None)
        modified_at = getattr(info, "modified_at", None)
    out: dict[str, Any] = {"path": path}
    if is_dir is not None:
        out["is_dir"] = bool(is_dir)
    if size is not None:
        out["size"] = int(size)
    if modified_at is not None:
        out["modified_at"] = modified_at
    return out

def workspace_api_path(raw: str) -> str:
    """Map dashboard ``/`` / ``/foo`` paths to workspace-relative fragments for I/O."""
    text = raw.strip().replace("\\", "/")
    if not text or text == "/":
        return "."
    return text.lstrip("/")

def _is_attachment_path_hint_text(text: str) -> bool:
    """True when *text* is an LLM-only ``[Attachment]/`` / ``[附件]`` path hint."""
    stripped = text.strip()
    if not stripped:
        return False
    first = stripped.split("\n", 1)[0].strip()
    return first.startswith("[Attachment] ") or first.startswith("[附件] ")

from typing import Any


def _is_history_noise_image_block(block: Any) -> bool:
    """True for vision blocks that must not appear as user-authored history text."""
    if not isinstance(block, dict):
        return False
    if str(block.get("type") or "").lower() != "image_url":
        return False
    if str(block.get("workspace_path") or "").strip():
        return True
    url_field = block.get("image_url")
    url = ""
    if isinstance(url_field, dict):
        url = str(url_field.get("url") or "")
    elif isinstance(url_field, str):
        url = url_field
    return url.startswith("data:") or url.startswith("workspace://")

from typing import Any


def _merge_adjacent_messages(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Collapse fragmented assistant text; keep each user turn separate."""
    merged: list[dict[str, Any]] = []
    for msg in messages:
        role = str(msg.get("role") or "")
        content = str(msg.get("content") or "")
        if not content:
            continue
        entry = {
            "role": role,
            "content": content,
            **({"id": msg["id"]} if msg.get("id") else {}),
        }
        if role == "user":
            merged.append(entry)
            continue
        if merged and merged[-1]["role"] == role:
            merged[-1]["content"] = f"{merged[-1]['content']}\n\n{content}"
            if msg.get("id"):
                merged[-1]["id"] = msg["id"]
            continue
        merged.append(entry)
    return merged

import re


def _title_after(lines, idx):
    """Title printed on the line(s) after a bare 'Chapter N' heading (slide title pages)."""
    out = []
    for line in lines[idx + 1: idx + 4]:
        s = line.strip()
        if not s or len(s) > 80 or re.match(r"^\s*(section|§|\d+\.\d+|by\b|author|instructor|lecturer|prof)", s, re.I):
            break
        out.append(s)
    return " ".join(out)

def find_text_top(info, needle):
    """Top y (PDF points) of the first text box whose text starts with `needle`.

    PDF text rectangles may split a heading ("Problem 4." | "[10 points] Trees"), so shorter
    prefixes are tried when the long one is not found.
    """
    flat = " ".join(needle.split()).lower()
    boxes = [(t, " ".join(text.split()).lower()) for l, b, r, t, text in info.text_boxes]
    for n in (40, 20, 10):
        key = flat[:n]
        if not key:
            continue
        for top, text in boxes:
            if text.startswith(key):
                return top
    return None

import struct
import zlib


def png_bytes(width, height, channels, stride, buf):
    """Encode a raw RGB/RGBA bitmap (top-down rows) as PNG using only zlib."""
    color_type = 6 if channels == 4 else 2
    raw = bytearray()
    row_len = width * channels
    for y in range(height):
        start = y * stride
        raw.append(0)
        raw += buf[start:start + row_len]

    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        return c + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", width, height, 8, color_type, 0, 0, 0)
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) + chunk(b"IDAT", zlib.compress(bytes(raw), 6)) + chunk(b"IEND", b"")

def _as_bool(v):
    """Coerce a flag to bool — accepts JSON booleans and 0/1 (judge.py emits integers); None passes through."""
    if v is None or isinstance(v, bool):
        return v
    if isinstance(v, int) and v in (0, 1):
        return bool(v)
    return None

def _q_is_visual(q):
    """A lecture/figure item: it carries (or may carry) a question-side visual asset."""
    if q.get("requires_assets") or q.get("maybe_requires_assets"):
        return True
    if q.get("question_text_status") in ("stub", "page_reference"):
        return True
    for a in (q.get("assets") or []):
        if isinstance(a, dict) and a.get("role") in ("question_context", "figure", "diagram", "table"):
            return True
    return False

def _section(text, header_keywords):
    """Lines under the first '## ' header containing ANY of header_keywords, until the next '## '."""
    if isinstance(header_keywords, str):
        header_keywords = [header_keywords]
    out, grab = [], False
    for ln in (text or "").splitlines():
        if ln.startswith("## "):
            grab = any(k in ln for k in header_keywords)
            continue
        if grab:
            out.append(ln)
    return "\n".join(out)

def require_consistent_asset_names(value: object, seen: dict[str, str] | None = None) -> None:
    """Reject manifests where one public filename refers to different bytes."""
    if seen is None:
        seen = {}
    if isinstance(value, dict):
        if isinstance(value.get("file"), str) and isinstance(value.get("sha256"), str):
            filename = value["file"]
            checksum = value["sha256"]
            if filename in seen and seen[filename] != checksum:
                raise SystemExit(f"public asset name has conflicting contents: {filename}")
            seen[filename] = checksum
        for child in value.values():
            require_consistent_asset_names(child, seen)
    elif isinstance(value, list):
        for child in value:
            require_consistent_asset_names(child, seen)

def ocr_consensus(frame_results, banners):
    """Consensus over PRE-OCR'd frames (each = [(text,conf,h),...]). Label = the
    candidate string recurring across the most frames (temporal consensus kills
    transient narration; the persistent part caption wins). Tiebreak by size*conf."""
    from collections import defaultdict
    score = defaultdict(lambda: [0, 0.0, 0.0])   # key -> [frame_count, sum_score, best_conf]
    rep = {}
    for res in frame_results:
        seen = set()
        for t, conf, h in res:
            if conf < 0.4 or len(t) < 3 or any(t.lower() in b or b in t.lower() for b in banners):
                continue
            key = t.lower().replace(" ", "")
            rep.setdefault(key, t)
            if key not in seen:
                score[key][0] += 1; seen.add(key)
            score[key][1] += h * conf
            score[key][2] = max(score[key][2], conf)
    if not score:
        return None, 0.0
    best = max(score.items(), key=lambda kv: (kv[1][0], kv[1][1]))
    return rep[best[0]], round(best[1][2], 2)

def _source_of(r: dict) -> str:
    """Recording source (youtube/tiktok/reddit) from a clip's wav path."""
    w = r.get("wav", "") or ""
    for s in ("youtube", "tiktok", "reddit"):
        if f"/{s}/" in w:
            return s
    return r.get("source", "?")

import json


def parse_json(text):
    """Best-effort extract the first JSON object/array from a completion."""
    for a, b in (("{", "}"), ("[", "]")):
        i, j = text.find(a), text.rfind(b)
        if 0 <= i < j:
            try:
                return json.loads(text[i:j + 1])
            except json.JSONDecodeError:
                pass
    return None

import hashlib


def split_of(group):
    """Deterministic 80/10/10 by group hash, stable across runs."""
    h = int(hashlib.md5(group.encode()).hexdigest(), 16) % 100
    return "train" if h < 80 else ("val" if h < 90 else "test")

from collections.abc import Callable, Mapping
from typing import Any, cast


def _validate_arguments(schema: Mapping[str, Any], raw: Any) -> str | None:
    """Validate the small JSON Schema subset used by this teaching chapter."""

    if not isinstance(raw, Mapping):
        return "arguments must be an object"
    if any(not isinstance(key, str) for key in raw):
        return "argument names must be strings"

    properties = schema.get("properties", {})
    required = schema.get("required", [])
    missing = [name for name in required if name not in raw]
    if missing:
        return f"missing required argument(s): {', '.join(missing)}"

    if schema.get("additionalProperties") is False:
        unknown = sorted(set(raw) - set(properties))
        if unknown:
            return f"unknown argument(s): {', '.join(unknown)}"

    json_types: dict[str, tuple[type, ...]] = {
        "string": (str,),
        "integer": (int,),
        "number": (int, float),
        "boolean": (bool,),
        "object": (Mapping,),
        "array": (list,),
    }
    for name, value in raw.items():
        rule = properties.get(name)
        if not isinstance(rule, Mapping):
            continue
        expected = rule.get("type")
        accepted = json_types.get(expected)
        # JSON booleans are not integers even though bool subclasses int in Python.
        if accepted and (not isinstance(value, accepted) or expected in {"integer", "number"} and isinstance(value, bool)):
            return f"argument {name!r} must be {expected}"
        if "minimum" in rule and value < rule["minimum"]:
            return f"argument {name!r} must be >= {rule['minimum']}"
    return None

