def dedup_file_reads(messages: list) -> tuple[list, int]:
    """Layer 2: Remove duplicate file reads, keep only the latest.

    When the agent reads the same file multiple times, older reads
    are redundant. We track read_file tool calls and remove older
    results for the same path.

    Returns: (modified messages, tokens saved)
    """
    # Track metadata on tool results
    # In real implementation, we'd correlate tool_use and tool_result
    # by ID. Teaching version: we tag results during execution.

    # Find the latest read of each file path
    latest_reads: dict[str, int] = {}  # path -> msg index
    for mi, msg in enumerate(messages):
        content = msg.get("content")
        if not isinstance(content, list):
            continue
        for block in content:
            if not isinstance(block, dict):
                continue
            if block.get("type") == "tool_result":
                path = block.get("_read_path")
                if path:
                    latest_reads[path] = mi

    # Remove older reads of the same file
    saved = 0
    for mi, msg in enumerate(messages):
        content = msg.get("content")
        if not isinstance(content, list):
            continue
        new_content = []
        for block in content:
            if not isinstance(block, dict):
                new_content.append(block)
                continue
            if block.get("type") == "tool_result":
                path = block.get("_read_path")
                if path and latest_reads.get(path, mi) > mi:
                    # This is an older read — skip it
                    saved += len(str(block.get("content", ""))) // 4
                    continue
            new_content.append(block)
        msg["content"] = new_content

    return messages, saved

def svg_wrapper(content: str, height: int = 400) -> str:
    """Wrap SVG content with proper viewBox."""
    return f'<svg viewBox="0 0 680 {height}" xmlns="http://www.w3.org/2000/svg">{content}</svg>'

from typing import Any, Callable, Iterable


def extract_publishable_key(payload: Any) -> str:
    """Extract the Stripe publishable key for the checkout handoff."""
    if isinstance(payload, dict):
        for key in ("publishable_key", "publishableKey"):
            value = str(payload.get(key) or "").strip()
            if value.startswith(("pk_live_", "pk_test_")):
                return value
        for value in payload.values():
            found = extract_publishable_key(value)
            if found:
                return found
    elif isinstance(payload, list):
        for value in payload:
            found = extract_publishable_key(value)
            if found:
                return found
    return ""

import re


def proxy_region_code(proxy: str | None) -> str:
    """Extract provider region code from URLs like ...-region-JP-sid-..."""
    if not proxy:
        return ""
    text = str(proxy)
    patterns = (
        r"(?:^|[-_./?&])region[-_=/]?([A-Za-z]{2})(?:[-_./?&]|$)",
        r"(?:^|[-_./?&])(?:country|cc|loc)[-_=/]?([A-Za-z]{2})(?:[-_./?&]|$)",
    )
    for pat in patterns:
        m = re.search(pat, text, flags=re.I)
        if m:
            return m.group(1).upper()
    return ""

from typing import Any, Callable, Optional


def _loaded_skill_names(messages: list[dict[str, Any]]) -> set[str]:
    """Skills whose instructions successfully entered THIS conversation (a load_skill call
    with a non-error result). Drives the disable countermand: a menu quietly shrinking is
    passive, but instructions already in history keep steering the model unless it is
    explicitly asked to stop."""
    import json as _json

    results: dict[str, str] = {}
    for m in messages:
        if m.get("role") == "tool" and m.get("tool_call_id"):
            content = m.get("content")
            results[m["tool_call_id"]] = (
                content if isinstance(content, str) else _json.dumps(content)
            )
    loaded: set[str] = set()
    for m in messages:
        if m.get("role") != "assistant" or not m.get("tool_calls"):
            continue
        for tc in m["tool_calls"]:
            fn = tc.get("function") or {}
            if fn.get("name") != "load_skill":
                continue
            try:
                name = str(_json.loads(fn.get("arguments") or "{}").get("name", ""))
            except Exception:
                continue
            result = results.get(tc.get("id", ""), "")
            if name and '"instructions"' in result:
                loaded.add(name)
    return loaded

from typing import Any, Optional


def content_to_text(content: Any, *, image_placeholder: str = "[image]") -> str:
    """Flatten message content (string or parts) to text — for titles, previews, search.
    Images render as `image_placeholder` (pass "" to drop them, e.g. for clean titles).
    """
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        out = []
        for part in content:
            if not isinstance(part, dict):
                continue
            if part.get("type") == "text":
                out.append(str(part.get("text", "")))
            elif part.get("type") == "image_url" and image_placeholder:
                out.append(image_placeholder)
            elif part.get("type") == "file" and image_placeholder:
                out.append("[pdf]")
        return " ".join(out).strip()
    return ""

