def split_thread(chat_id: str) -> tuple[str, Optional[int]]:
    """`owner/repo#N` → ("owner/repo", N); a bare repo has no thread number."""
    repo, _, num = chat_id.partition("#")
    try:
        return repo, int(num) if num else None
    except ValueError:
        return repo, None

def _slack_blocks(text: str, buttons) -> list[dict]:
    """A Block Kit message: a text section + a row of action buttons (action_id `ocw_<i>`,
    value = the encoded item id + resolution)."""
    blocks: list[dict] = [{"type": "section", "text": {"type": "mrkdwn", "text": text}}]
    if buttons:
        blocks.append(
            {
                "type": "actions",
                "elements": [
                    {
                        "type": "button",
                        "text": {"type": "plain_text", "text": b.label[:75]},
                        "value": b.value,
                        "action_id": f"ocw_{i}",
                    }
                    for i, b in enumerate(buttons)
                ],
            }
        )
    return blocks

def window(seconds: int) -> str:
    """The span a rollup covers, as short as it can honestly be said — ``24h``, ``7d``, ``30m``.

    Derived from what the relay sent rather than hardcoded: the window is an operator knob, and
    a label reading "24h" while the master counted six would be wrong in the one way a figure
    must never be. Days only from two up — a day is "24h" to anyone talking about what a machine
    did today, and 86400 is the default, so that is the string almost every readout carries.
    """
    if seconds <= 0:
        return ""
    if seconds % 86400 == 0 and seconds >= 172800:
        return f"{seconds // 86400}d"
    if seconds % 3600 == 0:
        return f"{seconds // 3600}h"
    if seconds % 60 == 0:
        return f"{seconds // 60}m"
    return f"{seconds}s"

from typing import TYPE_CHECKING, Any


def _validated(networks: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Trust-boundary check: refuse to persist a bundle we can't name or select later."""
    for net in networks:
        if not net.get("network_id") or not net.get("name"):
            raise SystemExit(
                "Control plane returned a malformed grid token; "
                "aborting to avoid corrupting local credentials."
            )
    return networks

def _listed(tokens: tuple[str, ...]) -> str:
    """``("a", "b", "c")`` → ``"a, b and c"`` — the closed set, read out in a sentence."""
    if len(tokens) < 2:
        return "".join(tokens)
    return f"{', '.join(tokens[:-1])} and {tokens[-1]}"

from typing import Any


def _model_case_map(overview: dict[str, Any]) -> dict[str, str]:
    """``lower(id) -> id``, read from the overview's own top-level ``models`` list.

    That list is the ONE place the relay reports a model's id in its true case; every node's own
    ``models`` array is lowercased for display (grid-leave issue: reproduced live serving
    `Qwen3.5-2B-Q4_K_M`, listed under a node as `qwen3.5-2b-q4_k_m`, and rejected verbatim when
    copied back into `grid chat -m`). Correcting it here, once, fixes it everywhere this renders —
    `grid engines`, `grid models`, and `grid launch`'s preflight (`live_model_names`) all read
    through this same function now, so none of them can show a name the grid won't answer to."""
    entries = overview.get("models")
    if not isinstance(entries, list):
        return {}
    return {
        entry["id"].lower(): entry["id"]
        for entry in entries
        if isinstance(entry, dict) and isinstance(entry.get("id"), str)
    }

def _add_answered(running: dict[str, int] | None, extra: dict[str, int]) -> dict[str, int]:
    """Fold one rollup into a running total. The window is one setting on one relay, so every row
    agrees; the first one seen is the one reported."""
    if running is None:
        return dict(extra)
    return {
        "window_seconds": running["window_seconds"] or extra["window_seconds"],
        "tokens_in": running["tokens_in"] + extra["tokens_in"],
        "tokens_cached": running["tokens_cached"] + extra["tokens_cached"],
        "tokens_out": running["tokens_out"] + extra["tokens_out"],
        "requests": running["requests"] + extra["requests"],
    }

