from typing import List


def generate_dot_trick_emails(username: str, domain: str = "gmail.com", max_count: int = 50) -> List[str]:
    """Generates unique dot-trick email variations for Gmail addresses."""
    cleaned_user = username.replace(".", "").strip().lower()
    if not cleaned_user:
        return []

    def generate_dots(s: str) -> List[str]:
        if len(s) <= 1:
            return [s]
        sub = generate_dots(s[1:])
        res = []
        for v in sub:
            res.append(s[0] + v)
            res.append(s[0] + "." + v)
        return res

    all_variations = generate_dots(cleaned_user)
    unique_list = []
    for v in all_variations:
        full_email = f"{v}@{domain}"
        if full_email not in unique_list:
            unique_list.append(full_email)
        if len(unique_list) >= max_count:
            break

    return unique_list

def encode_varint(value: int) -> bytes:
    """Encode a non-negative integer as a base-128 varint."""
    if value < 0:
        raise ValueError("varint must be non-negative")
    out = bytearray()
    while True:
        byte = value & 0x7F
        value >>= 7
        if value:
            out.append(byte | 0x80)
        else:
            out.append(byte)
            return bytes(out)

from typing import Any, Dict, List, Optional, Tuple


def extract_cookies_from_auth_client(client: Any) -> Dict[str, str]:
    """Best-effort dump of name->value cookies from XConsoleAuthClient."""
    out: Dict[str, str] = {}
    try:
        jar = client._t.cookies  # type: ignore[attr-defined]
    except Exception:
        return out
    # dict-like
    try:
        if hasattr(jar, "items"):
            for k, v in jar.items():
                if k and v is not None:
                    out[str(k)] = str(v)
            if out:
                return out
    except Exception:
        pass
    # curl_cffi jar iteration
    try:
        iterable = jar.jar if hasattr(jar, "jar") else jar
        for ck in iterable:
            name = getattr(ck, "name", None)
            value = getattr(ck, "value", None)
            if name and value is not None:
                out[str(name)] = str(value)
    except Exception:
        pass
    return out

def map_list_boss_active_status(job):
    """Map list-API job fields to ``boss_active_status``.

    BOSS ``/wapi/zpgeek/search/joblist.json`` typically exposes ``bossOnline``
    but not ``activeTimeDesc``. Prefer ``activeTimeDesc`` when present;
    otherwise map ``bossOnline=True`` to 「在线」. Detailed labels such as
    「刚刚活跃」still come from the detail path.
    """
    if not isinstance(job, dict):
        return ""
    desc = str(job.get("activeTimeDesc") or "").strip()
    if desc:
        return desc
    if job.get("bossOnline"):
        return "在线"
    return ""

