def _pick_groups(in_ch: int, out_ch: int, max_g: int = 4) -> int:
    """Safe group selection."""
    for g in (max_g, 2, 1):
        if in_ch % g == 0 and out_ch % g == 0:
            return g
    return 1

def fix_state_dict_prefix(state_dict: dict, is_distributed: bool) -> dict:
    """Add or strip the 'module.' DDP prefix to match the model wrapper."""
    first_key = next(iter(state_dict))
    if is_distributed and not first_key.startswith('module.'):
        return {f'module.{k}': v for k, v in state_dict.items()}
    if not is_distributed and first_key.startswith('module.'):
        return {k[len('module.'):]: v for k, v in state_dict.items()}
    return state_dict

def strip_state_dict_prefixes(state_dict: dict) -> dict:
    """Remove DDP ('module.') and torch.compile ('_orig_mod.') key prefixes.

    Single-GPU training wraps the model in ``torch.compile``, whose ``state_dict()``
    prefixes every key with ``_orig_mod.``; DDP adds ``module.``. Both (in any order
    or nesting) are stripped so checkpoints load into a plain model.
    """
    prefixes = ('module.', '_orig_mod.')

    def _clean(key: str) -> str:
        changed = True
        while changed:
            changed = False
            for p in prefixes:
                if key.startswith(p):
                    key = key[len(p):]
                    changed = True
        return key

    return {_clean(k): v for k, v in state_dict.items()}

def _grid_to_dict(grid) -> dict:
    """Canonical dict form of a parsed ``GridDocument`` (peer of ``idoc.to_dict()``).

    The grid model carries no ``to_dict``; this projects its load-bearing fields
    into a stable shape for the content hash. Empty containers are omitted so the
    hash matches what an equivalent minimal input would produce.
    """
    out: dict = {"cells": dict(grid.cells), "regions": dict(grid.regions)}
    if grid.formats:
        out["formats"] = dict(grid.formats)
    if grid.charts:
        out["charts"] = [dict(c) for c in grid.charts]
    return out

def normalize_hex(value: str) -> str:
    """Normalize any accepted hex spelling to 6-digit uppercase ``RRGGBB``.

    Accepts ``#rgb``, ``#rrggbb``, ``rgb``, ``rrggbb`` in any case. A leading
    ``#`` is stripped; a 3-digit shorthand is expanded by doubling each nibble.

    Raises:
        ValueError: if ``value`` is not a 3- or 6-digit hex string.
    """
    s = value.strip().lstrip("#").upper()
    if len(s) == 3 and all(c in "0123456789ABCDEF" for c in s):
        return "".join(c * 2 for c in s)
    if len(s) == 6 and all(c in "0123456789ABCDEF" for c in s):
        return s
    raise ValueError(f"not a valid hex color: {value!r}")

def rgb_to_hex(r: int, g: int, b: int) -> str:
    """Return the normalized ``RRGGBB`` hex for 0-255 channel values (clamped)."""

    def clamp(x: int) -> int:
        return max(0, min(255, int(round(x))))

    return f"{clamp(r):02X}{clamp(g):02X}{clamp(b):02X}"

def authoring_hints_md(profile: dict) -> list[str]:
    """How to author content against this profile - role-first, never style-first."""
    lines = ["", "## Authoring hints", ""]
    lines.append(
        "- Pick blocks by MEANING using the role table above; the engine resolves"
    )
    lines.append(
        "  every role to the template's own artifacts. Never name a style, font,"
    )
    lines.append("  or hex anywhere in the input: the profile is the only source.")
    lines.append(
        "- Respect the ordered skeleton (Structure section, when present): cover"
    )
    lines.append(
        "  content first, derived indexes where the template keeps them, then the"
    )
    lines.append("  freeform body in the template's own order.")
    comp = profile.get("comprehension") or {}
    fragments = comp.get("fragments") or []
    if comp.get("status") == "present" and fragments:
        names = ", ".join(
            sorted(str(f.get("name") or f.get("id") or "?") for f in fragments)
        )
        lines.append(
            f"- REUSE the comprehended fragments ({names}) via `component`/`section`"
        )
        lines.append(
            "  blocks with `{{slot}}` values instead of re-deriving their layout."
        )
    else:
        lines.append(
            "- After `comprehend`, reusable fragments (components/sections) may be"
        )
        lines.append(
            "  available in `profile.json` under `comprehension.fragments`: prefer"
        )
        lines.append("  them over re-deriving recurring layouts.")
    return lines

def palette_roles_md(profile: dict) -> list[str]:
    """The semantic palette-role table: the COLOR TOKENS an author may name."""
    theme = profile.get("theme") or {}
    proles = theme.get("palette_roles") or {}
    if not proles:
