from typing import List


def atempo_chain(factor: float) -> str:
    """atempo accepts 0.5..100 per instance; chain for extreme factors."""
    parts: List[str] = []
    remaining = factor
    while remaining < 0.5:
        parts.append("atempo=0.5")
        remaining /= 0.5
    while remaining > 100.0:
        parts.append("atempo=100.0")
        remaining /= 100.0
    parts.append(f"atempo={remaining:.6f}")
    return ",".join(parts)

def declared_unavailable(notes: str, key: str) -> bool:
    """True when analysis_notes.md declares this fact unavailable AND says what was searched."""
    for line in (notes or "").splitlines():
        if 'NOT AVAILABLE' in line.upper() and key in line:
            rest = line.split(':', 1)[1] if ':' in line else ''
            return len(rest.replace(key, '').strip(' -—\t')) >= 12
    return False

import re


def normalize_tag(tag: str) -> str:
    """Normalise a BCP-47-ish tag: 'ZH_hans' -> 'zh-Hans'."""
    if not tag:
        return ""
    parts = re.split(r"[-_]", tag.strip())
    out = [parts[0].lower()]
    for p in parts[1:]:
        out.append(p.upper() if len(p) == 2 else p.title())
    return "-".join(out)

def fill_todos(node):
    """Replace every TODO / empty prose slot so the Phase 8 gate can pass in a test."""
    if isinstance(node, dict):
        return {k: fill_todos(v) for k, v in node.items()}
    if isinstance(node, list):
        return [fill_todos(v) for v in node]
    if isinstance(node, str) and "TODO" in node:
        return "synthetic test value"
    return node

def summarize(payload):
    """Pull the two counters out without assuming the exact shape."""
    def grab(key):
        d = payload.get(key)
        if not isinstance(d, dict):
            return None, None
        util = d.get("utilization", d.get("used", d.get("percentage")))
        return util, d.get("resets_at", d.get("reset_at"))

    five, five_reset = grab("five_hour")
    seven, seven_reset = grab("seven_day")
    return five, five_reset, seven, seven_reset

def attrs_to_dict(attrs):
    """OTLP KeyValue list -> flat dict."""
    out = {}
    for a in attrs or []:
        k = a.get("key")
        v = a.get("value", {})
        if "stringValue" in v:
            out[k] = v["stringValue"]
        elif "intValue" in v:
            try:
                out[k] = int(v["intValue"])
            except (TypeError, ValueError):
                out[k] = v["intValue"]
        elif "doubleValue" in v:
            out[k] = v["doubleValue"]
        elif "boolValue" in v:
            out[k] = v["boolValue"]
        elif "arrayValue" in v:
            out[k] = [list(x.values())[0] if x else None
                      for x in v["arrayValue"].get("values", [])]
        else:
            out[k] = v
    return out

def norm_name(name):
    """Claude Code sets the log body to `claude_code.api_request` but the
    `event.name` attribute to bare `api_request`. Normalize to the long form."""
    if not name:
        return "unknown"
    return name if name.startswith("claude_code.") else f"claude_code.{name}"

