def _environment_value(env: Mapping[str, str], name: str) -> str:
    """Read an environment variable case-insensitively for Windows maps."""
    direct = env.get(name)
    if direct is not None:
        return str(direct)
    wanted = name.casefold()
    for key, value in env.items():
        if str(key).casefold() == wanted:
            return str(value)
    return ""

def build_digest(endpoints):
    """Render the endpoint list into the block the AI reads."""
    parts = []
    for e in endpoints:
        block = [f"### {e['method']} {e['path']}  -> {e['status']}"]
        if e["query"]:
            block.append(f"query: {e['query']}")
        if e["request_body"]:
            block.append(f"request body:\n{e['request_body']}")
        if e["response_body"]:
            block.append(f"response body:\n{e['response_body']}")
        parts.append("\n".join(block))
    return "\n\n".join(parts)

def base_url(flows, host):
    """Reconstruct the scheme://host base from a captured request."""
    for f in flows:
        req = f.get("request")
        if req and req["host"] == host:
            scheme = req.get("scheme", "https")
            port = req.get("port")
            netloc = host
            if port and port not in (80, 443):
                netloc = f"{host}:{port}"
            return f"{scheme}://{netloc}"
    return f"https://{host}"

import base64
import binascii


def _content_bytes(content):
    """Bytes of a HAR response content block, decoding base64 when flagged."""
    if not content:
        return b""
    text = content.get("text", "")
    if not text:
        return b""
    if content.get("encoding") == "base64":
        try:
            return base64.b64decode(text)
        except (binascii.Error, ValueError):
            return text.encode("utf-8")
    return text.encode("utf-8")

import json


def _decode(raw, limit=4000):
    """Best-effort decode of a body to a truncated JSON/text string for the AI."""
    if not raw:
        return ""
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return f"<{len(raw)} bytes binary>"
    try:  # pretty-print + truncate JSON so the AI sees structure, not noise
        text = json.dumps(json.loads(text), indent=2)
    except ValueError:
        pass
    return text[:limit] + ("\n…(truncated)" if len(text) > limit else "")

from typing import Any


def derive_break_point(score: dict[str, Any] | None) -> bool:
    """True when the current point is a break point. Conservative on nulls."""
    if not score:
        return False
    if score.get("is_tiebreak"):
        return False
    server = score.get("server")
    if server not in (1, 2):
        return False
    points = score.get("points") or []
    if len(points) != 2 or points[0] is None or points[1] is None:
        return False
    receiver_points = str(points[1] if server == 1 else points[0])
    server_points = str(points[0] if server == 1 else points[1])
    if receiver_points == "AD":
        return True
    return receiver_points == "40" and server_points in ("0", "15", "30")

