import re


def parse_dynadot_price(value: str) -> dict:
    """Parse Dynadot's current and legacy English price sentences."""
    if not isinstance(value, str):
        return {}
    registration = re.search(r"Registration Price:\s*([0-9]+(?:\.[0-9]+)?)", value,
                             re.IGNORECASE)
    renewal = re.search(r"Renewal price:\s*([0-9]+(?:\.[0-9]+)?)", value,
                        re.IGNORECASE)
    if registration:
        registration_value = float(registration.group(1))
    else:
        current = re.findall(r"([0-9]+(?:\.[0-9]+)?)\s+in\s+USD", value,
                             re.IGNORECASE)
        if not current:
            return {}
        registration_value = float(current[0])
    renewal_value = float(renewal.group(1)) if renewal else registration_value
    if not renewal:
        current = re.findall(r"([0-9]+(?:\.[0-9]+)?)\s+in\s+USD", value,
                             re.IGNORECASE)
        if len(current) > 1:
            renewal_value = float(current[1])
    lowered = value.lower()
    premium = "premium" in lowered and not re.search(
        r"not\s+(?:a\s+)?premium(?:\s+domain)?", lowered)
    return {
        "registration": registration_value,
        "renewal": renewal_value,
        "premium": premium,
    }

def _level_for_minutes(minutes):
    """Map Claude active minutes to the shared five-stop heatmap ramp."""
    try:
        value = int(minutes or 0)
    except (TypeError, ValueError):
        value = 0
    if value <= 0:
        return 0
    if value < 15:
        return 1
    if value < 60:
        return 2
    if value < 180:
        return 3
    return 4

import json


def _render(value):
    """Stringify a JSON value the way a person reads it, not the way it stores."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if value is None:
        return ""
    if isinstance(value, (dict, list)):
        try:
            return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False)
        except (TypeError, ValueError):
            return str(value)
    return str(value)

def normalize_options(raw):
    """Flatten Claude / Codex option shapes into `{label, description}`.

    Models mostly send `{label, description}`, but bare strings and the odd
    `title` / `name` alias show up enough that refusing them looked like a
    parse failure on the phone.
    """
    options = []
    if not isinstance(raw, list):
        return options
    for option in raw:
        if isinstance(option, dict):
            label = (
                option.get("label")
                or option.get("title")
                or option.get("name")
                or option.get("text")
            )
            description = option.get("description")
        else:
            label, description = option, None
        if not isinstance(label, str) or not label.strip():
            continue
        options.append({
            "label": " ".join(label.split()),
            "description": (
                " ".join(description.split())
                if isinstance(description, str) and description.strip()
                else None
            ),
        })
    return options

def _monitor_open_from_fields(monitor):
    """True/False/None when the list payload already carries status."""
    for key in ("status", "state", "currentState", "current_state",
                "alertState", "alert_state"):
        value = monitor.get(key)
        if isinstance(value, str) and value.strip():
            low = value.strip().lower()
            if low in ("open", "alerting", "firing", "triggered", "active"):
                return True
            if low in ("closed", "ok", "resolved", "inactive", "normal"):
                return False
    return None

def _fmt_rate(value):
    """Rates span three orders of magnitude across pools; keep them legible."""
    if value is None:
        return None
    if value >= 10:
        return f"{value:.0f}"
    if value >= 1:
        return f"{value:.1f}"
    # Sub-1 rates need two places to say anything, but "0.20" reads worse
    # than "0.2" in a sentence.
    return f"{value:.2f}".rstrip("0").rstrip(".")

