import hashlib


def _key_to_int(value) -> int:
    """Normalize a key (int / digit-string / passphrase) to a non-negative int.

    A pure integer or all-digits string is used directly; anything else is
    treated as a passphrase and hashed (SHA-256) into a 256-bit integer.
    """
    if isinstance(value, int):
        return abs(value)
    s = str(value).strip()
    if not s:
        raise ValueError("empty Gaussian-Shading key")
    if s.lstrip("-").isdigit():
        return abs(int(s))
    return int.from_bytes(hashlib.sha256(s.encode()).digest(), "big")

import json


def _extract_json_object(text: str) -> dict:
    """Pull the first balanced top-level JSON object out of a possibly-wrapped string."""
    if not text:
        raise ValueError("empty response")
    # Strip code fences
    if text.lstrip().startswith("```"):
        text = text.strip().strip("`")
        if text.lstrip().startswith("json"):
            text = text.lstrip()[4:]
    start = text.find("{")
    if start == -1:
        raise ValueError(f"no JSON object found in: {text[:120]!r}")
    depth = 0
    for i in range(start, len(text)):
        c = text[i]
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return json.loads(text[start : i + 1])
    raise ValueError(f"unbalanced JSON object: {text[start:start+120]!r}")

def _as_list(val, default, n):
    """Broadcast a scalar/None to a length-n list, or validate a given list."""
    if val is None:
        return [default] * n
    if isinstance(val, (list, tuple)):
        if len(val) != n:
            raise ValueError(f"expected {n} values, got {len(val)}")
        return list(val)
    return [val] * n

import re


def categorize(endpoints: list) -> dict:
    """Group endpoints by type"""
    cats = {
        "login": [], "api": [], "admin": [], "upload": [],
        "redirect": [], "search": [], "config": [], "other": []
    }
    patterns = {
        "login":    r"(login|signin|auth|sso|oauth)",
        "api":      r"(/api/|/graphql|/v\d+/|/rest/)",
        "admin":    r"(admin|dashboard|panel|wp-admin|cpanel)",
        "upload":   r"(upload|import|attachment)",
        "redirect": r"(redirect|callback|return_to|url=|dest=|next=)",
        "search":   r"[/?](search|find)[/?]|search\?",
        "config":   r"(\.env|\.git|\.bak|config|debug|phpinfo)",
    }
    for ep in endpoints:
        matched = False
        for cat, pat in patterns.items():
            if re.search(pat, ep, re.I):
                cats[cat].append(ep)
                matched = True
                break
        if not matched:
            cats["other"].append(ep)
    return {k: sorted(v) for k, v in cats.items() if v}

import re


def parse_whatweb(raw: str) -> dict:
    """Parse whatweb output into tech stack dict"""
    ansi = re.compile(r'\x1b\[[0-9;]*[a-zA-Z]')
    raw_clean = ansi.sub('', raw)
    result = {}
    for line in raw_clean.strip().splitlines():
        if " [" not in line:
            continue
        parts = line.split(" [", 1)
        url = parts[0].strip()
        rest = parts[1].split("]", 1)
        if len(rest) < 2:
            continue
        tags_raw = rest[1].strip().rstrip(",")

        tech = {"server": "", "cms": "", "cdn": "", "lang": "", "headers": []}
        current = ""
        depth = 0
        tags = []
        for ch in tags_raw:
            if ch == "[":
                depth += 1
                current += ch
            elif ch == "]":
                depth -= 1
                current += ch
            elif ch == "," and depth == 0:
                tags.append(current.strip())
                current = ""
            else:
                current += ch
        if current.strip():
            tags.append(current.strip())

        for tag in tags:
            tag = tag.strip()
            if not tag:
                continue
            if "[" in tag:
                key, val = tag.split("[", 1)
                val = val.rstrip("]")
            else:
                key, val = tag, ""

            k = key.lower()
            if "httpserver" in k:
                tech["server"] = val
            elif "x-powered-by" in k:
                tech["cms"] = val
            elif k in ("cloudflare", "cloudfront"):
                tech["cdn"] = key
            elif k in ("next.js", "php", "asp_net", "laravel", "django", "ruby"):
                tech["lang"] = val or key
            elif any(h in k for h in ("x-", "strict-transport", "content-security")):
                tech["headers"].append(key)

        result[url] = {k: v for k, v in tech.items() if v}
        if "server" not in result[url] and "cms" not in result[url]:
            result[url]["server"] = "unknown"
    return result

import re


def risk_score(ep: str) -> int:
    """0-10 based on vulnerability surface"""
    if re.search(r"/_next/|/static/|\.(css|js|png|jpg|ico|svg|woff|woff2|ttf|map)$", ep, re.I):
        return 0
    score = 1
    if any(w in ep.lower() for w in ["login","auth","admin","dashboard","api","upload"]):
        score += 3
    if "?" in ep:
        score += 2
    if any(w in ep.lower() for w in ["id=","user=","file=","page=","redirect=","url="]):
        score += 3
    return min(score, 10)

def _remap_single_codebook_keys(state_dict: dict) -> dict:
    """Adapt legacy multi-codebook checkpoints to the single-stream LMModel.

    Older checkpoints store the token embedding and output head as the first
    entry of an ``nn.ModuleList`` (``emb.0.*`` / ``linears.0.*``). LMModel is
    single-stream, so those map to ``emb.*`` / ``linear.*``. Checkpoints with a
    second codebook (``emb.1.*`` etc.) are unsupported and rejected.
    """
    if any(k.startswith(("emb.1.", "linears.1.")) for k in state_dict):
        raise ValueError(
            "Checkpoint has more than one codebook (n_q > 1); "
            "only single-stream models are supported."
        )
    remapped = {}
    for key, value in state_dict.items():
        if key.startswith("emb.0."):
            key = "emb." + key[len("emb.0.") :]
        elif key.startswith("linears.0."):
            key = "linear." + key[len("linears.0.") :]
        remapped[key] = value
    return remapped

