def _focus_units(
    units: dict[str, dict[str, Any]],
    edge_weights: dict[tuple[str, str], int],
    focus_prefix: str,
) -> tuple[set[str], set[str]]:
    """Return (units inside the focus prefix, those plus their direct import neighbours)."""
    inside = {unit_id for unit_id in units if unit_id == focus_prefix or unit_id.startswith(focus_prefix + "/")}
    neighbours: set[str] = set()
    for (source, target) in edge_weights:
        if source in inside:
            neighbours.add(target)
        if target in inside:
            neighbours.add(source)
    return inside, inside | neighbours

def _suffix_prefix_overlap(value: str, secret: str) -> int:
    """Find a cap-bisected secret in linear time and bounded memory."""
    limit = min(len(value), len(secret) - 1)
    if limit <= 0:
        return 0
    prefix = secret[:limit]
    failure = [0] * len(prefix)
    matched = 0
    for index in range(1, len(prefix)):
        while matched and prefix[index] != prefix[matched]:
            matched = failure[matched - 1]
        if prefix[index] == prefix[matched]:
            matched += 1
        failure[index] = matched
    matched = 0
    for character in value[-limit:]:
        while matched and character != prefix[matched]:
            matched = failure[matched - 1]
        if character == prefix[matched]:
            matched += 1
            if matched == len(prefix):
                return matched
    return matched

def recheck_safety_profile_revision(carried: str, live: str | None) -> str:
