def compute_candidate_signature(definition: Mapping[str, Any]) -> str:
    """Return the canonical artifact signature for a mining candidate definition."""
    kind = definition.get("kind")
    if kind == "existing_strategy":
        strategy_id = definition.get("strategy_id")
        if not isinstance(strategy_id, str) or not strategy_id:
            raise ValueError("existing strategy candidate requires strategy_id")
        return f"strategy:{strategy_id}"
    if kind != "factor_rank":
        raise ValueError(f"unsupported mining candidate kind: {kind!r}")

    factor_names = definition.get("factor_names")
    scoring = definition.get("scoring")
    directions = definition.get("directions")
    if not isinstance(factor_names, list) or not factor_names:
        raise ValueError("factor candidate requires factor_names")
    if not isinstance(scoring, Mapping) or set(scoring) != set(factor_names):
        raise ValueError("factor candidate scoring keys must match factor_names")
    if not isinstance(directions, Mapping) or set(directions) != set(factor_names):
        raise ValueError("factor candidate direction keys must match factor_names")

    weights: list[str] = []
    direction_values: list[str] = []
    for factor_name in factor_names:
        if not isinstance(factor_name, str) or not factor_name:
            raise ValueError("factor names must be non-empty strings")
        value = scoring[factor_name]
        if isinstance(value, bool):
            raise ValueError("factor weights must be numeric")
        try:
            weight = float(value)
        except (TypeError, ValueError) as exc:
            raise ValueError("factor weights must be numeric") from exc
        if not math.isfinite(weight) or weight <= 0.0:
            raise ValueError("factor weights must be finite and positive")
        direction = directions[factor_name]
        if direction not in {"high", "low"}:
            raise ValueError("factor directions must be high or low")
        weights.append(f"{weight:g}")
        direction_values.append("1" if direction == "high" else "-1")
    return (
        f"factor:{','.join(factor_names)}|w:{','.join(weights)}"
        f"|d:{','.join(direction_values)}"
    )

from typing import Any


def extract_rows(payload: Any, response_path: str = "") -> list[dict]:
    """Extract a list of row dicts from a JSON payload using dot-path lookup."""
    data = payload
    if response_path:
        for part in response_path.split("."):
            if not part:
                continue
            if isinstance(data, dict):
                data = data.get(part)
            else:
                data = None
                break
    if data is None:
        return []
    if isinstance(data, dict):
        return [data]
    if isinstance(data, list):
        return [item for item in data if isinstance(item, dict)]
    return []

def is_configured(config: dict) -> bool:
    """Return whether the non-secret fields are sufficient to attempt delivery."""
    sender = str(config.get("from_address") or config.get("username") or "").strip()
    recipients = config.get("to_addresses") or []
    return bool(config.get("host") and sender and recipients)

def batch_interval(rpm: int | None, *, default: float = 0.0) -> float:
    """Return the existing uniform batch interval formula: 60 / rpm."""
    return 60.0 / rpm if rpm and rpm > 0 else default

def _sanitize_sample(obj: object) -> object:
    """Keep structure; drop long arrays and obvious secret-like strings."""
    if isinstance(obj, dict):
        out = {}
        for k, v in obj.items():
            lk = str(k).lower()
            if any(s in lk for s in ("key", "token", "secret", "password", "authorization")):
                out[k] = "***"
            else:
                out[k] = _sanitize_sample(v)
        return out
    if isinstance(obj, list):
        if len(obj) > 3:
            return [_sanitize_sample(x) for x in obj[:3]] + [f"...(+{len(obj) - 3} more)"]
        return [_sanitize_sample(x) for x in obj]
    if isinstance(obj, str) and len(obj) > 120:
        return obj[:120] + "..."
    return obj

def merge_pairs(merges):
    """Normalise merges to (left, right) and reject a repeated pair."""
    pairs, seen = [], {}
    for rank, merge in enumerate(merges):
        left, right = merge.split(" ", 1) if isinstance(merge, str) else merge
        if (left, right) in seen:
            raise SystemExit(
                f"merges {seen[(left, right)]} and {rank} are both "
                f"{left!r} + {right!r}; one pair cannot have two ranks"
            )
        seen[(left, right)] = rank
        pairs.append((left, right))
    return pairs

def record_tag(r):
    """Tag as recorded, or as embedded in the run name."""
    if "tag" in r:
        return r["tag"] or ""
    name = r.get("name", "")
    arm = r.get("arm", "")
    if name.startswith(arm + "-"):
        rest = name[len(arm) + 1:]
        return rest.rsplit("-s", 1)[0] if "-s" in rest else ""
    return ""

def _safe_evaluate(page, js: str):
    """Run page.evaluate, swallowing the benign 'Execution context was destroyed'
    error that fires when a navigation (e.g. the post-login redirect) happens to
    land mid-evaluate. Returns None on any such transient failure instead of
    raising, so callers can just retry on the next poll."""
    try:
        return page.evaluate(js)
    except Exception as e:
        msg = str(e)
        if "Execution context was destroyed" in msg or "navigation" in msg.lower():
            return None
        raise

def _biz(data: dict) -> dict:
    """Unwrap DeepSeek's `data.biz_data` envelope, raising on API-level errors."""
    if data.get("code") != 0:
        raise RuntimeError(f"DeepSeek API error: {data.get('msg') or data}")
    biz = data.get("data", {}).get("biz_data")
    if biz is None:
        raise RuntimeError(f"Unexpected response shape: {data}")
    return biz

def _capture_message_id(meta: dict, snapshot: dict) -> None:
    """Best-effort: pull the assistant message_id out of a snapshot frame.

    DeepSeek nests the assistant message under `response`; we check there first,
    then the snapshot root, accepting `message_id` or `id`.
    """
    for container in (snapshot.get("response"), snapshot):
        if isinstance(container, dict):
            mid = container.get("message_id", container.get("id"))
            if isinstance(mid, int):
                meta["message_id"] = mid
                return

def _hashcash_ok(digest: bytes, difficulty: int) -> bool:
    """True if ``digest`` has at least ``difficulty`` leading zero bits."""
    full, rem = difficulty // 8, difficulty % 8
    for i in range(full):
        if digest[i] != 0:
            return False
    if rem:
        mask = (255 << (8 - rem)) & 0xFF
        if digest[full] & mask != 0:
            return False
    return True

import math


def solve_copilot_challenge(parameter: str) -> str:
    """Solve the arithmetic ``copilot`` challenge: round((a^3/100 + a*25) % 22)."""
    a = float(parameter)
    return str(int(math.floor(((a ** 3 / 100 + a * 25) % 22) + 0.5)))

def is_accepted_format(data: bytes) -> str:
    """Determine the MIME type of image data."""
    if data.startswith(b'\x89PNG\r\n\x1a\n'):
        return 'image/png'
    elif data.startswith(b'\xff\xd8'):
        return 'image/jpeg'
    return 'application/octet-stream'

def _header_value(headers: dict[str, str], name: str) -> str:
    """Case-insensitive header lookup (Starlette headers are already
    case-insensitive, but this keeps the module usable with a plain dict)."""
    lowered = name.lower()
    for key, value in headers.items():
        if key.lower() == lowered:
            return str(value or "")
    return ""

import re


def _lowered_snippet(text: str) -> str:
    """A tidy fragment to hang off a lead phrase (leading verb lower-cased)."""
    text = (text or "").strip()
    if not text:
        return ""
    # Lower-case only a leading all-alpha word so "Prefers X" -> "prefers X" reads
    # naturally after "You" without mangling proper nouns mid-sentence.
    match = re.match(r"^([A-Za-z]+)(\b.*)$", text)
    if match and match.group(1).isalpha():
        return match.group(1).lower() + match.group(2)
    return text

def _clean_line(text: str) -> str:
    """Collapse whitespace/newlines so one cited fact never breaks the block into
    multiple Markdown lines (which would desync from its citation footnote)."""
    text = str(text or "").replace("\r\n", " ").replace("\n", " ").replace("\r", " ")
    return " ".join(text.split())

def _renumber_communities(
    node_ids: list[str], labels: dict[str, str]
) -> dict[str, int]:
    """Renumber raw string labels into stable integer community ids ``0..k-1``.

    Communities are ordered by their ascending smallest member id, so the id a
    community receives depends only on its membership — not on iteration order or
    the raw label value. Isolated nodes (their own singleton label) simply become
    their own singleton community.
    """
    # Smallest member id per raw label (node_ids is sorted, so the first node
    # observed for a label is that label's smallest member).
    smallest_member: dict[str, str] = {}
    for nid in node_ids:
        label = labels[nid]
        if label not in smallest_member:
            smallest_member[label] = nid

    ordered_labels = sorted(smallest_member, key=lambda lab: smallest_member[lab])
    label_to_cid = {label: cid for cid, label in enumerate(ordered_labels)}
    return {nid: label_to_cid[labels[nid]] for nid in node_ids}

def _weighted_degree_centrality(
    node_ids: list[str], adjacency: dict[str, dict[str, float]]
) -> dict[str, float]:
    """Weighted-degree centrality, normalized to ``[0, 1]`` by the max.

    Each node's raw score is the sum of its incident (deduped, weight-summed)
    edge weights. We normalize by the maximum raw score across nodes so the most
    central entity scores ``1.0``. Isolated nodes score ``0.0``; if *every* node
    is isolated (max == 0) all scores are ``0.0`` (divide-by-zero guard).
    """
    raw: dict[str, float] = {
        nid: sum(adjacency[nid].values()) for nid in node_ids
    }
    max_raw = max(raw.values()) if raw else 0.0
    if max_raw <= 0.0:
        return {nid: 0.0 for nid in node_ids}
    return {nid: raw[nid] / max_raw for nid in node_ids}

def make_tileable_rgb(payload: bytes, size: int, blend_fraction: float = 0.08) -> bytes:
    """Blend opposite border pairs so repeated offline maps do not expose hard seams."""
    if len(payload) != size * size * 3:
        raise ValueError("tileable RGB payload has the wrong size")
    output = bytearray(payload)
    blend = max(1, min(size // 4, round(size * blend_fraction)))

    def blend_pair(first: int, second: int, weight: float) -> None:
        for channel in range(3):
            average = (output[first + channel] + output[second + channel]) * 0.5
            output[first + channel] = round(output[first + channel] * (1 - weight) + average * weight)
            output[second + channel] = round(output[second + channel] * (1 - weight) + average * weight)

    for offset in range(blend):
        weight = 1 - offset / blend
        for y in range(size):
            left = (y * size + offset) * 3
            right = (y * size + size - 1 - offset) * 3
            blend_pair(left, right, weight)
        for x in range(size):
            top = (offset * size + x) * 3
            bottom = ((size - 1 - offset) * size + x) * 3
            blend_pair(top, bottom, weight)
    return bytes(output)

def blind_scout_phase_id(pass_id: str) -> str:
    """Map legacy pass aliases to the four user-facing phase scopes."""

    normalized = str(pass_id or "").strip().lower()
    if normalized in {"blockout", "structure", "structural-pass"}:
        return "blockout"
    if normalized in {"form", "form-refinement"}:
        return "form"
    if normalized in {"lookdev", "material-pass", "surface-pass", "lighting-pass"}:
        return "lookdev"
    if normalized in {"interaction", "interaction-pass"}:
        return "interaction"
    return normalized

